import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const record = value as Record<string, unknown>;
  return (
    typeof record.id === "string" &&
    typeof record.name === "string" &&
    typeof record.email === "string"
  );
}

function parseUsers(data: unknown): User[] {
  if (!Array.isArray(data) || !data.every(isUser)) {
    throw new Error("Received malformed user data");
  }
  return data;
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    const term = query.trim();
    if (!term) {
      setUsers([]);
      setLoading(false);
      setError(null);
      return;
    }

    let ignore = false;
    const controller = new AbortController();

    // Reflects "search pending" for the whole debounce+fetch window, and clears
    // results tied to the previous query so stale data can't be mistaken for a match.
    setUsers([]);
    setLoading(true);
    setError(null);

    const timer = setTimeout(() => {
      fetch(`/api/users?q=${encodeURIComponent(term)}`, {
        signal: controller.signal,
      })
        .then((res) => {
          if (!res.ok) {
            throw new Error(`Request failed with status ${res.status}`);
          }
          return res.json();
        })
        .then((body: unknown) => {
          if (ignore) return;
          setUsers(parseUsers(body));
          setLoading(false);
        })
        .catch((err: unknown) => {
          if (ignore) return;
          if (err instanceof DOMException && err.name === "AbortError") {
            return;
          }
          setError(err instanceof Error ? err.message : "Failed to fetch users");
          setUsers([]);
          setLoading(false);
        });
    }, DEBOUNCE_MS);

    return () => {
      ignore = true;
      clearTimeout(timer);
      controller.abort();
    };
  }, [query]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label>
          Sort by:{" "}
          <select
            value={sortField}
            onChange={(e) => setSortField(e.target.value as SortField)}
          >
            <option value="name">Name</option>
            <option value="email">Email</option>
          </select>
        </label>
      </div>

      {loading && <div role="status">Loading...</div>}
      {error && <div role="alert">Error: {error}</div>}

      {!loading && !error && query.trim() !== "" && (
        <div>{sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}</div>
      )}

      <ul>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            {user.name} &lt;{user.email}&gt;
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;

function isMetric(value: unknown): value is Metric {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as Record<string, unknown>).name === "string" &&
    typeof (value as Record<string, unknown>).value === "number" &&
    Number.isFinite((value as Record<string, unknown>).value) &&
    typeof (value as Record<string, unknown>).unit === "string"
  );
}

function parseMetrics(data: unknown): Metric[] {
  if (!Array.isArray(data) || !data.every(isMetric)) {
    throw new Error("Received malformed metrics response");
  }
  return data;
}

async function fetchMetrics(signal: AbortSignal): Promise<Metric[]> {
  const res = await fetch("/api/metrics", { signal });
  if (!res.ok) {
    throw new Error(`Failed to load metrics: ${res.status}`);
  }
  return parseMetrics(await res.json());
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [, setTick] = useState(0);

  const previousValuesRef = useRef<Map<string, number>>(new Map());
  const activeControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    let cancelled = false;

    const refresh = async () => {
      if (document.hidden) return;

      // Abort any in-flight request first so an overlapping refresh (interval
      // firing while a visibility-triggered fetch is still pending, or vice
      // versa) can never resolve after a newer one and overwrite fresh data.
      activeControllerRef.current?.abort();
      const controller = new AbortController();
      activeControllerRef.current = controller;

      try {
        const data = await fetchMetrics(controller.signal);
        if (cancelled || activeControllerRef.current !== controller) return;

        const previousValues = previousValuesRef.current;
        const nextChanged = new Set<string>();
        const nextValues = new Map<string, number>();
        for (const metric of data) {
          const prev = previousValues.get(metric.name);
          if (prev !== undefined && prev !== metric.value) {
            nextChanged.add(metric.name);
          }
          nextValues.set(metric.name, metric.value);
        }
        previousValuesRef.current = nextValues;

        setMetrics(data);
        setChangedNames(nextChanged);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (cancelled || controller.signal.aborted) return;
        setError(err instanceof Error ? err.message : "Failed to load metrics");
      }
    };

    void refresh();
    const intervalId = window.setInterval(refresh, POLL_INTERVAL_MS);

    const handleVisibilityChange = () => {
      if (!document.hidden) {
        void refresh();
      }
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      activeControllerRef.current?.abort();
      window.clearInterval(intervalId);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    const timerId = window.setInterval(() => setTick((t) => t + 1), 1_000);
    return () => window.clearInterval(timerId);
  }, []);

  const secondsAgo = lastUpdated
    ? Math.max(0, Math.round((Date.now() - lastUpdated.getTime()) / 1000))
    : null;

  return (
    <div className="metrics-panel">
      <div className="metrics-panel__header">
        <h2>Metrics</h2>
        <span className="metrics-panel__updated">
          {secondsAgo === null ? "Loading…" : `Last updated ${secondsAgo}s ago`}
        </span>
      </div>

      {error && <div className="metrics-panel__error">{error}</div>}

      <ul className="metrics-panel__list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? "metrics-panel__item metrics-panel__item--changed"
                : "metrics-panel__item"
            }
          >
            <span className="metrics-panel__name">{metric.name}</span>
            <span className="metrics-panel__value">
              {metric.value}
              {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === 'string' &&
    typeof candidate.value === 'number' &&
    Number.isFinite(candidate.value) &&
    typeof candidate.unit === 'string'
  );
}

function isMetricArray(value: unknown): value is Metric[] {
  if (!Array.isArray(value) || !value.every(isMetric)) {
    return false;
  }
  const names = new Set((value as Metric[]).map((metric) => metric.name));
  return names.size === value.length;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<number | null>(null);
  const [secondsAgo, setSecondsAgo] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const previousValues = useRef<Map<string, number>>(new Map());
  const abortControllerRef = useRef<AbortController | null>(null);
  const requestIdRef = useRef(0);

  const fetchMetrics = useCallback(async () => {
    abortControllerRef.current?.abort();
    const controller = new AbortController();
    abortControllerRef.current = controller;
    const requestId = ++requestIdRef.current;

    try {
      const response = await fetch('/api/metrics', { signal: controller.signal });
      if (!response.ok) {
        throw new Error(`Request failed with status ${response.status}`);
      }
      const data: unknown = await response.json();
      if (!isMetricArray(data)) {
        throw new Error('Received malformed metrics data');
      }
      if (requestId !== requestIdRef.current) {
        return;
      }

      const nextChanged = new Set<string>();
      for (const metric of data) {
        const previousValue = previousValues.current.get(metric.name);
        if (previousValue !== undefined && previousValue !== metric.value) {
          nextChanged.add(metric.name);
        }
      }
      previousValues.current = new Map(data.map((metric) => [metric.name, metric.value]));

      setMetrics(data);
      setChangedNames(nextChanged);
      setLastUpdated(Date.now());
      setError(null);
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') {
        return;
      }
      if (requestId !== requestIdRef.current) {
        return;
      }
      setError(err instanceof Error ? err.message : 'Failed to load metrics');
    }
  }, []);

  useEffect(() => {
    fetchMetrics();

    let intervalId: ReturnType<typeof setInterval> | null = null;

    const startPolling = () => {
      if (intervalId === null) {
        intervalId = setInterval(fetchMetrics, POLL_INTERVAL_MS);
      }
    };

    const stopPolling = () => {
      if (intervalId !== null) {
        clearInterval(intervalId);
        intervalId = null;
      }
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        fetchMetrics();
        startPolling();
      }
    };

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      stopPolling();
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      abortControllerRef.current?.abort();
    };
  }, [fetchMetrics]);

  useEffect(() => {
    if (lastUpdated === null) {
      return;
    }

    const updateSecondsAgo = () => {
      setSecondsAgo(Math.max(0, Math.round((Date.now() - lastUpdated) / 1000)));
    };

    updateSecondsAgo();
    const tickId = setInterval(updateSecondsAgo, 1000);
    return () => clearInterval(tickId);
  }, [lastUpdated]);

  return (
    <div className="metrics-panel">
      <div className="metrics-panel__header">
        <h2>Metrics</h2>
        <span className="metrics-panel__timestamp">
          {lastUpdated === null ? 'Loading…' : `Last updated ${secondsAgo} seconds ago`}
        </span>
      </div>
      {error !== null && <p className="metrics-panel__error">{error}</p>}
      <ul className="metrics-panel__list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? 'metrics-panel__item metrics-panel__item--changed'
                : 'metrics-panel__item'
            }
          >
            <span className="metrics-panel__name">{metric.name}</span>
            <span className="metrics-panel__value">
              {metric.value}
              {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

