import { useEffect, useMemo, useState } from "react";

interface User {
  id: string | number;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    (typeof candidate.id === "string" || typeof candidate.id === "number") &&
    typeof candidate.name === "string" &&
    typeof candidate.email === "string"
  );
}

function parseUsers(data: unknown): User[] {
  if (!Array.isArray(data) || !data.every(isUser)) {
    throw new Error("Received malformed user data from server");
  }
  return data;
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  const isStale = query !== debouncedQuery;

  useEffect(() => {
    if (query) {
      setLoading(true);
    }
    const handle = setTimeout(() => {
      setDebouncedQuery(query);
    }, DEBOUNCE_MS);
    return () => clearTimeout(handle);
  }, [query]);

  useEffect(() => {
    if (!debouncedQuery) {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json();
      })
      .then((data: unknown) => {
        setUsers(parseUsers(data));
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (controller.signal.aborted) {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
        setUsers([]);
        setLoading(false);
      });

    return () => controller.abort();
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label>
          Sort by:{" "}
          <select
            value={sortField}
            onChange={(e) => setSortField(e.target.value as SortField)}
          >
            <option value="name">Name</option>
            <option value="email">Email</option>
          </select>
        </label>
      </div>

      {loading && <div role="status">Loading...</div>}
      {error && <div role="alert">Error: {error}</div>}

      {!loading && !error && !isStale && debouncedQuery && (
        <div>{sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}</div>
      )}

      {!loading && !error && !isStale && (
        <ul>
          {sortedUsers.map((user) => (
            <li key={user.id}>
              <span>{user.name}</span> &mdash; <span>{user.email}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

import { useState, FormEvent } from "react";

interface FormValues {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormValues, string>>;

const INITIAL_VALUES: FormValues = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  if (!values.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!values.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(values.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!values.password) {
    errors.password = "Password is required.";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!values.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupResponse {
  id: string;
}

interface SignupErrorResponse {
  errors?: Record<string, string>;
}

const FORM_FIELDS = Object.keys(INITIAL_VALUES) as Array<keyof FormValues>;

function sanitizeFieldErrors(errors: unknown): FieldErrors {
  const sanitized: FieldErrors = {};
  if (typeof errors !== "object" || errors === null) {
    return sanitized;
  }

  for (const field of FORM_FIELDS) {
    const value = (errors as Record<string, unknown>)[field];
    if (typeof value === "string") {
      sanitized[field] = value;
    }
  }

  return sanitized;
}

function isSignupResponse(data: unknown): data is SignupResponse {
  return (
    typeof data === "object" &&
    data !== null &&
    typeof (data as Record<string, unknown>).id === "string"
  );
}

export default function SignupForm() {
  const [values, setValues] = useState<FormValues>(INITIAL_VALUES);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);

  function updateField<K extends keyof FormValues>(field: K, value: FormValues[K]) {
    setValues((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting) {
      return;
    }
    setSubmitError(null);
    setAccountId(null);

    const clientErrors = validate(values);
    if (Object.keys(clientErrors).length > 0) {
      setErrors(clientErrors);
      return;
    }

    setSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: values.name,
          email: values.email,
          password: values.password,
          acceptTerms: values.acceptTerms,
        }),
      });

      if (!response.ok) {
        const data: SignupErrorResponse = await response.json().catch(() => ({}));
        const fieldErrors = sanitizeFieldErrors(data.errors);
        if (Object.keys(fieldErrors).length > 0) {
          setErrors(fieldErrors);
        } else {
          setSubmitError("Something went wrong. Please try again.");
        }
        return;
      }

      const data: unknown = await response.json().catch(() => null);
      if (!isSignupResponse(data)) {
        setSubmitError("Something went wrong. Please try again.");
        return;
      }
      setAccountId(data.id);
      setValues(INITIAL_VALUES);
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  if (accountId) {
    return (
      <div role="status">
        <p>Account created successfully! Your account id is {accountId}.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          name="name"
          type="text"
          autoComplete="name"
          value={values.name}
          onChange={(e) => updateField("name", e.target.value)}
          disabled={submitting}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <span id="name-error">{errors.name}</span>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          name="email"
          type="email"
          autoComplete="email"
          value={values.email}
          onChange={(e) => updateField("email", e.target.value)}
          disabled={submitting}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <span id="email-error">{errors.email}</span>}
