import { useEffect, useRef, useState } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

interface ChatRoomProps {
  roomId: string;
}

const RECONNECT_DELAY_MS = 2000;

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.author === "string" &&
    typeof v.text === "string" &&
    typeof v.sentAt === "string"
  );
}

export default function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [messagesRoomId, setMessagesRoomId] = useState(roomId);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);

  // Reset messages synchronously during render (not in an effect) so the
  // previous room's messages never paint for the new room.
  if (roomId !== messagesRoomId) {
    setMessagesRoomId(roomId);
    setMessages([]);
  }

  useEffect(() => {
    // Cancellation token scoped to this effect run: unlike a shared ref,
    // it can't be reset by the next effect's setup, so a stale onclose from
    // the previous room can never schedule a reconnect for this room, and
    // stale onopen/onmessage callbacks can't touch this room's state either.
    let cancelled = false;
    let socket: WebSocket | null = null;

    const connect = () => {
      if (cancelled) return;

      socket = new WebSocket(`wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`);
      socketRef.current = socket;

      socket.onopen = () => {
        if (cancelled) return;
        setIsReconnecting(false);
      };

      socket.onmessage = (event) => {
        if (cancelled) return;
        try {
          const parsed: unknown = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed]);
          }
        } catch (error) {
          console.warn("Received malformed chat message", error);
        }
      };

      socket.onclose = () => {
        if (cancelled) return;
        setIsReconnecting(true);
        reconnectTimerRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      };

      socket.onerror = () => {
        socket?.close();
      };
    };

    connect();

    return () => {
      cancelled = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      socketRef.current?.close();
      socketRef.current = null;
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = () => {
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(JSON.stringify({ text }));
    setDraft("");
  };

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    sendMessage();
  };

  return (
    <div className="chat-room">
      {isReconnecting && <div className="chat-room__banner">Reconnecting…</div>}

      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form className="chat-room__composer" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;

const styles: Record<string, React.CSSProperties> = {
  panel: {
    border: "1px solid #d0d7de",
    borderRadius: 8,
    padding: 16,
    maxWidth: 480,
    fontFamily: "system-ui, sans-serif",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "baseline",
    marginBottom: 12,
  },
  title: {
    margin: 0,
    fontSize: 16,
    fontWeight: 600,
  },
  updated: {
    fontSize: 12,
    color: "#57606a",
  },
  error: {
    color: "#cf222e",
    fontSize: 13,
    marginBottom: 8,
  },
  table: {
    width: "100%",
    borderCollapse: "collapse",
  },
  row: {
    borderTop: "1px solid #eaeef2",
    transition: "background-color 0.6s ease",
  },
  rowChanged: {
    backgroundColor: "#fff8c5",
  },
  cell: {
    padding: "6px 4px",
    fontSize: 14,
    textAlign: "left",
  },
  valueCell: {
    padding: "6px 4px",
    fontSize: 14,
    textAlign: "right",
    fontVariantNumeric: "tabular-nums",
  },
};

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    Number.isFinite(candidate.value) &&
    typeof candidate.unit === "string"
  );
}

function isMetricArray(value: unknown): value is Metric[] {
  return Array.isArray(value) && value.every(isMetric);
}

function formatSecondsAgo(lastUpdated: Date | null, now: Date): string {
  if (lastUpdated === null) {
    return "never";
  }
  const seconds = Math.max(0, Math.round((now.getTime() - lastUpdated.getTime()) / 1000));
  if (seconds === 0) {
    return "just now";
  }
  return `${seconds} second${seconds === 1 ? "" : "s"} ago`;
}

export default function MetricsPanel(): React.JSX.Element {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<ReadonlySet<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState<Date>(() => new Date());

  const previousValuesRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    let cancelled = false;
    let isPolling = false;
    let pollTimeoutId: ReturnType<typeof setTimeout> | null = null;
    let generation = 0;

    async function fetchMetrics(generationAtStart: number): Promise<void> {
      try {
        const response = await fetch("/api/metrics");
        if (!response.ok) {
          throw new Error(`Request failed with status ${response.status}`);
        }
        const responseBody: unknown = await response.json();
        if (cancelled || generationAtStart !== generation) {
          return;
        }
        if (!isMetricArray(responseBody)) {
          throw new Error("Received malformed metrics data");
        }
        const fetchedMetrics = responseBody;

        const previousValues = previousValuesRef.current;
        const changed = new Set<string>();
        for (const metric of fetchedMetrics) {
          const previousValue = previousValues.get(metric.name);
          if (previousValue !== undefined && previousValue !== metric.value) {
            changed.add(metric.name);
          }
        }
        previousValuesRef.current = new Map(
          fetchedMetrics.map((metric) => [metric.name, metric.value]),
        );

        setMetrics(fetchedMetrics);
        setChangedNames(changed);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (!cancelled && generationAtStart === generation) {
          setError(err instanceof Error ? err.message : "Failed to load metrics");
        }
      }
    }

    async function pollOnce(generationAtStart: number): Promise<void> {
      await fetchMetrics(generationAtStart);
      if (isPolling && !cancelled && generationAtStart === generation) {
        pollTimeoutId = setTimeout(() => {
          void pollOnce(generationAtStart);
        }, POLL_INTERVAL_MS);
      }
    }

    function startPolling(): void {
      if (isPolling) {
        return;
      }
      isPolling = true;
      generation += 1;
      void pollOnce(generation);
    }

    function stopPolling(): void {
      isPolling = false;
      generation += 1;
      if (pollTimeoutId !== null) {
        clearTimeout(pollTimeoutId);
        pollTimeoutId = null;
      }
    }

    function handleVisibilityChange(): void {
      if (document.hidden) {
        stopPolling();
      } else {
        startPolling();
      }
    }

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      stopPolling();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    const tickId = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(tickId);
  }, []);

  return (
    <div style={styles.panel}>
      <div style={styles.header}>
        <h2 style={styles.title}>Metrics</h2>
        <span style={styles.updated}>Last updated {formatSecondsAgo(lastUpdated, now)}</span>
      </div>

      {error !== null && <div style={styles.error}>{error}</div>}

      {metrics.length === 0 && error === null ? (
        <div>Loading metrics…</div>
      ) : (
        <table style={styles.table}>
          <thead>
            <tr>
              <th style={styles.cell} scope="col">
                Name
              </th>
              <th style={styles.valueCell} scope="col">
                Value
              </th>
            </tr>
          </thead>
          <tbody>
            {metrics.map((metric) => {
              const rowStyle = changedNames.has(metric.name)
                ? { ...styles.row, ...styles.rowChanged }
                : styles.row;
              return (
                <tr key={metric.name} style={rowStyle}>
                  <td style={styles.cell}>{metric.name}</td>
                  <td style={styles.valueCell}>
                    {metric.value} {metric.unit}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}

import { useRef, useState, FormEvent } from "react";

interface FormValues {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormValues, string>>;

const initialValues: FormValues = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  if (!values.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!values.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_RE.test(values.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!values.password) {
    errors.password = "Password is required.";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!values.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupResponse {
  id: string;
}

interface SignupErrorResponse {
  errors?: Record<string, string>;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isSignupResponse(value: unknown): value is SignupResponse {
  return isRecord(value) && typeof value.id === "string";
}

function isFieldErrors(value: unknown): value is Record<string, string> {
  return (
    isRecord(value) &&
    Object.values(value).every((message) => typeof message === "string")
  );
}

function isSignupErrorResponse(value: unknown): value is SignupErrorResponse {
  if (!isRecord(value)) return false;
  if (value.errors === undefined) return true;
  return isFieldErrors(value.errors);
}

const FIELD_KEYS: (keyof FormValues)[] = [
  "name",
  "email",
  "password",
  "confirmPassword",
  "acceptTerms",
];

function pickKnownFieldErrors(errors: Record<string, string>): FieldErrors {
  const known: FieldErrors = {};
  for (const key of FIELD_KEYS) {
    if (typeof errors[key] === "string") {
      known[key] = errors[key];
    }
  }
  return known;
}

export default function SignupForm() {
  const [values, setValues] = useState<FormValues>(initialValues);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);
  const submittingRef = useRef(false);

  function handleChange<K extends keyof FormValues>(field: K, value: FormValues[K]) {
    setValues((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => {
      const next = { ...prev, [field]: undefined };
      // Password and confirmation are cross-validated, so an edit to either
      // one can invalidate an error message still displayed on the other.
      if (field === "password" || field === "confirmPassword") {
        next.confirmPassword = undefined;
      }
      return next;
    });
  }

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();

    if (submittingRef.current) {
      return;
    }

    const validationErrors = validate(values);
    setErrors(validationErrors);
    setSubmitError(null);

    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    const submittedValues = values;
    submittingRef.current = true;
    setSubmitting(true);
    try {
      const res = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: submittedValues.name,
          email: submittedValues.email,
          password: submittedValues.password,
          confirmPassword: submittedValues.confirmPassword,
          acceptTerms: submittedValues.acceptTerms,
        }),
      });

      if (!res.ok) {
        const errorBody: unknown = await res.json().catch(() => null);
        const knownFieldErrors =
          isSignupErrorResponse(errorBody) && errorBody.errors
            ? pickKnownFieldErrors(errorBody.errors)
            : undefined;
        if (knownFieldErrors && Object.keys(knownFieldErrors).length > 0) {
          setErrors(knownFieldErrors);
        } else {
          setSubmitError("Signup failed. Please try again.");
        }
        return;
      }

      const successBody: unknown = await res.json().catch(() => null);
      if (!isSignupResponse(successBody)) {
        setSubmitError("Unexpected response from server. Please try again.");
        return;
      }
      setAccountId(successBody.id);
      // Only clear fields the user hasn't touched since submitting; edits
      // made while the request was in flight are preserved.
      setValues((current) => (current === submittedValues ? initialValues : current));
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  }

  if (accountId) {
    return (
      <div role="status">
        <p>Account created successfully! Your account id is {accountId}.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={values.name}
          onChange={(e) => handleChange("name", e.target.value)}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <span id="name-error">{errors.name}</span>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={values.email}
          onChange={(e) => handleChange("email", e.target.value)}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <span id="email-error">{errors.email}</span>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={values.password}
          onChange={(e) => handleChange("password", e.target.value)}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <span id="password-error">{errors.password}</span>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm Password</label>
        <input
          id="confirmPassword"
          type="password"
          value={values.confirmPassword}
          onChange={(e) => handleChange("confirmPassword", e.target.value)}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && (
          <span id="confirmPassword-error">{errors.confirmPassword}</span>
        )}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={values.acceptTerms}
            onChange={(e) => handleChange("acceptTerms", e.target.checked)}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <span id="acceptTerms-error">{errors.acceptTerms}</span>}
      </div>

      {submitError && <div role="alert">{submitError}</div>}

      <button type="submit" disabled={submitting}>
        {submitting ? "Submitting..." : "Sign Up"}
      </button>
    </form>
  );
}

import { useEffect, useRef, useState, type FormEvent } from "react";

interface ChatMessage {
