const MAX_RECONNECT_DELAY_MS = 10_000;
const BASE_RECONNECT_DELAY_MS = 500;
const MAX_MESSAGES = 200;

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.author === "string" &&
    typeof candidate.text === "string" &&
    typeof candidate.sentAt === "string"
  );
}

export function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);
  const [prevRoomId, setPrevRoomId] = useState(roomId);

  if (roomId !== prevRoomId) {
    setPrevRoomId(roomId);
    setMessages([]);
    setDraft("");
  }

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const reconnectAttemptRef = useRef(0);
  const closingForSwitchRef = useRef(false);
  const bottomRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    reconnectAttemptRef.current = 0;
    closingForSwitchRef.current = false;

    let cancelled = false;

    const connect = () => {
      if (cancelled) return;

      const socket = new WebSocket(
        `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`,
      );
      socketRef.current = socket;

      socket.onopen = () => {
        if (cancelled) return;
        reconnectAttemptRef.current = 0;
        setIsReconnecting(false);
      };

      socket.onmessage = (event) => {
        if (cancelled) return;
        try {
          const parsed: unknown = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed].slice(-MAX_MESSAGES));
          }
        } catch (error) {
          console.warn("Failed to parse chat message payload", error);
        }
      };

      socket.onclose = () => {
        if (cancelled || closingForSwitchRef.current) return;
        setIsReconnecting(true);
        const attempt = reconnectAttemptRef.current + 1;
        reconnectAttemptRef.current = attempt;
        const delay = Math.min(
          BASE_RECONNECT_DELAY_MS * 2 ** (attempt - 1),
          MAX_RECONNECT_DELAY_MS,
        );
        reconnectTimeoutRef.current = setTimeout(connect, delay);
      };

      socket.onerror = () => {
        socket.close();
      };
    };

    connect();

    return () => {
      cancelled = true;
      closingForSwitchRef.current = true;
      if (reconnectTimeoutRef.current !== null) {
        clearTimeout(reconnectTimeoutRef.current);
        reconnectTimeoutRef.current = null;
      }
      socketRef.current?.close();
      socketRef.current = null;
    };
  }, [roomId]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ block: "end" });
  }, [messages]);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;
    socket.send(JSON.stringify({ text }));
    setDraft("");
  }, [draft]);

  const handleSubmit = useCallback(
    (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      sendMessage();
    },
    [sendMessage],
  );

  return (
    <div className="chat-room">
      {isReconnecting && <div className="chat-room__banner">Reconnecting…</div>}
      <ul className="chat-room__messages">
        {messages.map((message) => (
          <li key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <time className="chat-room__time" dateTime={message.sentAt}>
              {new Date(message.sentAt).toLocaleTimeString()}
            </time>
          </li>
        ))}
      </ul>
      <div ref={bottomRef} />
      <form className="chat-room__form" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

export default ChatRoom;

import { useState, useRef, FormEvent } from "react";

type FormFields = "name" | "email" | "password" | "confirmPassword" | "acceptTerms";

interface FormState {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<FormFields, string>>;

const initialState: FormState = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(form: FormState): FieldErrors {
  const errors: FieldErrors = {};

  if (!form.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!form.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(form.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!form.password) {
    errors.password = "Password is required.";
  } else if (form.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!form.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (form.confirmPassword !== form.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!form.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupSuccessResponse {
  id: string;
}

interface SignupErrorResponse {
  errors: Partial<Record<FormFields, string>>;
}

function isSignupErrorResponse(body: unknown): body is SignupErrorResponse {
  return (
    typeof body === "object" &&
    body !== null &&
    "errors" in body &&
    typeof (body as { errors: unknown }).errors === "object" &&
    (body as { errors: unknown }).errors !== null
  );
}

function isSignupSuccessResponse(body: unknown): body is SignupSuccessResponse {
  return (
    typeof body === "object" &&
    body !== null &&
    "id" in body &&
    typeof (body as { id: unknown }).id === "string"
  );
}

const FORM_FIELDS: FormFields[] = ["name", "email", "password", "confirmPassword", "acceptTerms"];

function sanitizeFieldErrors(raw: Partial<Record<FormFields, unknown>>): FieldErrors {
  const sanitized: FieldErrors = {};
  for (const field of FORM_FIELDS) {
    const value = raw[field];
    if (typeof value === "string" && value.trim()) {
      sanitized[field] = value;
    }
  }
  return sanitized;
}

export default function SignupForm() {
  const [form, setForm] = useState<FormState>(initialState);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);
  const submittingRef = useRef(false);

  function updateField<K extends keyof FormState>(field: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (submittingRef.current) {
      return;
    }

    setSubmitError(null);

    const validationErrors = validate(form);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    submittingRef.current = true;
    setSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: form.name,
          email: form.email,
          password: form.password,
          acceptTerms: form.acceptTerms,
        }),
      });

      const responseBody: unknown = await response.json().catch(() => null);

      if (!response.ok) {
        const fieldErrors = isSignupErrorResponse(responseBody)
          ? sanitizeFieldErrors(responseBody.errors)
          : {};
        if (Object.keys(fieldErrors).length > 0) {
          setErrors(fieldErrors);
        } else {
          setSubmitError("Something went wrong. Please try again.");
        }
        return;
      }

      if (!isSignupSuccessResponse(responseBody)) {
        setSubmitError("Unexpected response from server.");
        return;
      }

      setAccountId(responseBody.id);
      setForm(initialState);
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  }

  if (accountId) {
    return (
      <div role="status">
        <p>Account created successfully! Your account id is {accountId}.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <fieldset disabled={submitting}>
        <div>
          <label htmlFor="name">Name</label>
          <input
            id="name"
            type="text"
            value={form.name}
            onChange={(e) => updateField("name", e.target.value)}
            aria-invalid={errors.name ? true : undefined}
            aria-describedby={errors.name ? "name-error" : undefined}
          />
          {errors.name && (
            <span id="name-error" role="alert">
              {errors.name}
            </span>
          )}
        </div>

        <div>
          <label htmlFor="email">Email</label>
          <input
            id="email"
            type="email"
            value={form.email}
            onChange={(e) => updateField("email", e.target.value)}
            aria-invalid={errors.email ? true : undefined}
            aria-describedby={errors.email ? "email-error" : undefined}
          />
          {errors.email && (
            <span id="email-error" role="alert">
              {errors.email}
            </span>
          )}
        </div>

        <div>
          <label htmlFor="password">Password</label>
          <input
            id="password"
            type="password"
            value={form.password}
            onChange={(e) => updateField("password", e.target.value)}
            aria-invalid={errors.password ? true : undefined}
            aria-describedby={errors.password ? "password-error" : undefined}
          />
          {errors.password && (
            <span id="password-error" role="alert">
              {errors.password}
            </span>
          )}
        </div>

        <div>
          <label htmlFor="confirmPassword">Confirm Password</label>
          <input
            id="confirmPassword"
            type="password"
            value={form.confirmPassword}
            onChange={(e) => updateField("confirmPassword", e.target.value)}
            aria-invalid={errors.confirmPassword ? true : undefined}
            aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
          />
          {errors.confirmPassword && (
            <span id="confirmPassword-error" role="alert">
              {errors.confirmPassword}
            </span>
          )}
        </div>

        <div>
          <label htmlFor="acceptTerms">
            <input
              id="acceptTerms"
              type="checkbox"
              checked={form.acceptTerms}
              onChange={(e) => updateField("acceptTerms", e.target.checked)}
              aria-invalid={errors.acceptTerms ? true : undefined}
              aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
            />
            I accept the terms and conditions
          </label>
          {errors.acceptTerms && (
            <span id="acceptTerms-error" role="alert">
              {errors.acceptTerms}
            </span>
          )}
        </div>
      </fieldset>

      {submitError && <p role="alert">{submitError}</p>}

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import type { ChangeEvent, FormEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function isStorageAvailable(): boolean {
  return typeof window !== "undefined" && typeof window.localStorage !== "undefined";
}

function isTodo(value: unknown): value is Todo {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.text === "string" &&
    typeof candidate.done === "boolean"
  );
}

function loadTodos(): Todo[] {
  if (!isStorageAvailable()) return [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isTodo);
  } catch {
    return [];
  }
}

function createId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(() => loadTodos());
  const [newText, setNewText] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");
  const isCancelingEditRef = useRef(false);

  useEffect(() => {
    if (!isStorageAvailable()) return;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch {
      // Storage may be full or blocked (e.g. private browsing); ignore.
    }
  }, [todos]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos],
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function handleAdd(event: FormEvent) {
    event.preventDefault();
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [...prev, { id: createId(), text, done: false }]);
    setNewText("");
  }

  function handleToggle(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo,
      ),
    );
  }

  function handleDelete(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEdit(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEdit(id: string) {
    const text = editingText.trim();
    if (!text) {
      handleDelete(id);
      return;
    }
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, text } : todo)),
    );
    setEditingId(null);
    setEditingText("");
  }

  function moveUp(index: number) {
    if (index === 0) return;
    setTodos((prev) => {
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
  }

  function moveDown(index: number) {
    setTodos((prev) => {
      if (index === prev.length - 1) return prev;
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form onSubmit={handleAdd} className="todo-add-form">
        <input
          type="text"
          value={newText}
          placeholder="Add a new todo…"
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            setNewText(event.target.value)
          }
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-filters">
        {(["all", "active", "done"] as Filter[]).map((option) => (
          <button
            key={option}
            type="button"
            aria-pressed={filter === option}
            onClick={() => setFilter(option)}
          >
            {option[0].toUpperCase() + option.slice(1)}
          </button>
        ))}
      </div>

      <p className="todo-count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>

      <ul className="todo-list">
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((item) => item.id === todo.id);
          const isEditing = editingId === todo.id;
          return (
            <li key={todo.id} className="todo-item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => handleToggle(todo.id)}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(event: ChangeEvent<HTMLInputElement>) =>
                    setEditingText(event.target.value)
                  }
                  onBlur={() => {
                    if (isCancelingEditRef.current) {
                      isCancelingEditRef.current = false;
                      return;
                    }
                    commitEdit(todo.id);
                  }}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      event.preventDefault();
                      commitEdit(todo.id);
                    } else if (event.key === "Escape") {
                      isCancelingEditRef.current = true;
                      cancelEdit();
                    }
                  }}
                />
              ) : (
                <span
                  className={todo.done ? "todo-text done" : "todo-text"}
                  onDoubleClick={() => startEdit(todo)}
                >
                  {todo.text}
                </span>
              )}

              <div className="todo-actions">
                <button
                  type="button"
                  onClick={() => moveUp(index)}
                  disabled={index === 0}
                  aria-label="Move up"
                >
                  ↑
                </button>
                <button
                  type="button"
                  onClick={() => moveDown(index)}
                  disabled={index === todos.length - 1}
                  aria-label="Move down"
                >
                  ↓
                </button>
                {isEditing ? (
                  <button type="button" onClick={() => commitEdit(todo.id)}>
                    Save
                  </button>
                ) : (
                  <button type="button" onClick={() => startEdit(todo)}>
                    Edit
                  </button>
                )}
                <button type="button" onClick={() => handleDelete(todo.id)}>
                  Delete
                </button>
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    const valid = parsed.filter(
      (item): item is Todo =>
        item &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean"
    );
    const seenIds = new Set<string>();
    return valid.filter((todo) => {
      if (seenIds.has(todo.id)) return false;
      seenIds.add(todo.id);
      return true;
    });
  } catch {
    return [];
  }
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [hydrated, setHydrated] = useState(false);
  const [filter, setFilter] = useState<Filter>("all");
  const [draft, setDraft] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    setTodos(loadTodos());
    setHydrated(true);
  }, []);

  useEffect(() => {
    if (!hydrated) return;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch {
      // storage may be blocked or full; persistence is best-effort
    }
  }, [todos, hydrated]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos]
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function addTodo() {
    const text = draft.trim();
    if (!text) return;
    const newTodo: Todo = {
      id: crypto.randomUUID(),
      text,
      done: false,
    };
    setTodos((prev) => [...prev, newTodo]);
    setDraft("");
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo
      )
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEdit(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function commitEdit() {
    const text = editingText.trim();
    if (editingId === null) return;
    if (text) {
      setTodos((prev) =>
        prev.map((todo) =>
          todo.id === editingId ? { ...todo, text } : todo
        )
      );
    }
    setEditingId(null);
    setEditingText("");
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function swapById(prev: Todo[], idA: string, idB: string): Todo[] {
    const indexA = prev.findIndex((todo) => todo.id === idA);
    const indexB = prev.findIndex((todo) => todo.id === idB);
    if (indexA === -1 || indexB === -1) return prev;
    const next = [...prev];
    [next[indexA], next[indexB]] = [next[indexB], next[indexA]];
    return next;
  }

  function moveUp(id: string) {
    const index = visibleTodos.findIndex((todo) => todo.id === id);
    if (index <= 0) return;
    const targetId = visibleTodos[index - 1].id;
    setTodos((prev) => swapById(prev, id, targetId));
  }

  function moveDown(id: string) {
    const index = visibleTodos.findIndex((todo) => todo.id === id);
    if (index === -1 || index >= visibleTodos.length - 1) return;
    const targetId = visibleTodos[index + 1].id;
    setTodos((prev) => swapById(prev, id, targetId));
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          addTodo();
        }}
      >
        <input
          type="text"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          placeholder="Add a new todo..."
          aria-label="New todo text"
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-board__filters">
        {(["all", "active", "done"] as Filter[]).map((f) => (
          <button
            key={f}
            type="button"
            aria-pressed={filter === f}
            disabled={filter === f}
            onClick={() => setFilter(f)}
          >
            {f[0].toUpperCase() + f.slice(1)}
          </button>
        ))}
      </div>

      <ul className="todo-board__list">
        {visibleTodos.map((todo, index) => {
          const isFirst = index === 0;
          const isLast = index === visibleTodos.length - 1;
          const isEditing = editingId === todo.id;

          return (
            <li key={todo.id} className="todo-board__item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
                aria-label={`Mark "${todo.text}" as ${
                  todo.done ? "active" : "done"
                }`}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(e) => setEditingText(e.target.value)}
                  onBlur={commitEdit}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") commitEdit();
                    if (e.key === "Escape") cancelEdit();
                  }}
                  aria-label="Edit todo text"
                />
              ) : (
                <span
                  className={todo.done ? "todo-board__text--done" : ""}
                  onDoubleClick={() => startEdit(todo)}
                >
                  {todo.text}
                </span>
              )}

              <button
                type="button"
                onClick={() => moveUp(todo.id)}
                disabled={isFirst}
                aria-label={`Move "${todo.text}" up`}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveDown(todo.id)}
                disabled={isLast}
                aria-label={`Move "${todo.text}" down`}
              >
                ↓
              </button>
              <button
                type="button"
                onClick={() => startEdit(todo)}
                aria-label={`Edit "${todo.text}"`}
              >
                Edit
              </button>
              <button
                type="button"
                onClick={() => deleteTodo(todo.id)}
                aria-label={`Delete "${todo.text}"`}
              >
                Delete
              </button>
            </li>
          );
        })}
      </ul>

      <p className="todo-board__count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  isLoading: boolean;
  error: string | null;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [isLoading, setIsLoading] = useState(ids.length > 0);
  const [error, setError] = useState<string | null>(null);

  const key = JSON.stringify(ids);

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setIsLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setIsLoading(true);
    setError(null);

    Promise.all(
      ids.map(async (id) => {
        const response = await fetch(`/api/users/${encodeURIComponent(id)}`);
        if (!response.ok) {
          throw new Error(`Failed to load user ${id}: ${response.status}`);
        }
        const data: unknown = await response.json();
        if (!isUser(data)) {
          throw new Error(`Received malformed profile data for user ${id}`);
        }
        return data;
      }),
    )
      .then((users) => {
        if (cancelled) return;
        const byId: Record<string, User> = Object.create(null);
        for (const user of users) {
          byId[user.id] = user;
        }
        setProfiles(byId);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to load user profiles");
      })
      .finally(() => {
        if (cancelled) return;
        setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  return { profiles, isLoading, error };
}

import { useEffect, useRef, useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const isSavingRef = useRef(false);

  useEffect(() => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  }, [user]);

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  const handleReset = () => {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  };

  const handleSave = async () => {
    if (!hasChanges || isSavingRef.current) return;
    isSavingRef.current = true;
    setIsSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
