          {isSaving ? "Saving..." : "Save"}
        </button>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import type { ChangeEvent, FormEvent, KeyboardEvent, MouseEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

interface Editing {
  id: string;
  text: string;
}

const STORAGE_KEY = "todo-board-items";

function hasStorage(): boolean {
  return typeof window !== "undefined" && !!window.localStorage;
}

function loadTodos(): Todo[] {
  if (!hasStorage()) return [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    const seenIds = new Set<string>();
    const valid: Todo[] = [];
    for (const item of parsed) {
      if (
        typeof item === "object" &&
        item !== null &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean" &&
        !seenIds.has(item.id)
      ) {
        seenIds.add(item.id);
        valid.push(item as Todo);
      }
    }
    return valid;
  } catch {
    return [];
  }
}

function createId(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function matchesFilter(todo: Todo, filter: Filter): boolean {
  if (filter === "active") return !todo.done;
  if (filter === "done") return todo.done;
  return true;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [filter, setFilter] = useState<Filter>("all");
  const [newText, setNewText] = useState("");
  const [editing, setEditing] = useState<Editing | null>(null);
  const hasLoaded = useRef(false);

  useEffect(() => {
    setTodos(loadTodos());
    hasLoaded.current = true;
  }, []);

  useEffect(() => {
    if (!hasLoaded.current || !hasStorage()) return;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch {
      // storage may be full, disabled, or blocked (private browsing); persistence is best-effort
    }
  }, [todos]);

  function addTodo(e: FormEvent) {
    e.preventDefault();
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [...prev, { id: createId(), text, done: false }]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, done: !todo.done } : todo)),
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    setEditing((prev) => (prev?.id === id ? null : prev));
  }

  function startEditing(todo: Todo) {
    setEditing({ id: todo.id, text: todo.text });
  }

  function commitEdit() {
    setEditing((prev) => {
      if (!prev) return prev;
      const text = prev.text.trim();
      if (!text) {
        setTodos((ts) => ts.filter((t) => t.id !== prev.id));
      } else {
        setTodos((ts) => ts.map((t) => (t.id === prev.id ? { ...t, text } : t)));
      }
      return null;
    });
  }

  function cancelEdit() {
    setEditing(null);
  }

  function handleEditKeyDown(e: KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Enter") {
      commitEdit();
    } else if (e.key === "Escape") {
      cancelEdit();
    }
  }

  function preventBlur(e: MouseEvent) {
    e.preventDefault();
  }

  function moveTodo(id: string, direction: "up" | "down") {
    setTodos((prev) => {
      const visible = prev.filter((todo) => matchesFilter(todo, filter));
      const visibleIndex = visible.findIndex((todo) => todo.id === id);
      if (visibleIndex === -1) return prev;
      const targetVisibleIndex = direction === "up" ? visibleIndex - 1 : visibleIndex + 1;
      if (targetVisibleIndex < 0 || targetVisibleIndex >= visible.length) return prev;
      const targetId = visible[targetVisibleIndex].id;
      const next = [...prev];
      const i = next.findIndex((todo) => todo.id === id);
      const j = next.findIndex((todo) => todo.id === targetId);
      [next[i], next[j]] = [next[j], next[i]];
      return next;
    });
  }

  const visibleTodos = todos.filter((todo) => matchesFilter(todo, filter));

  const remainingCount = todos.filter((todo) => !todo.done).length;

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form onSubmit={addTodo}>
        <input
          type="text"
          value={newText}
          placeholder="Add a new task"
          onChange={(e: ChangeEvent<HTMLInputElement>) => setNewText(e.target.value)}
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-filters">
        {(["all", "active", "done"] as Filter[]).map((f) => (
          <button
            key={f}
            type="button"
            aria-pressed={filter === f}
            onClick={() => setFilter(f)}
          >
            {f[0].toUpperCase() + f.slice(1)}
          </button>
        ))}
      </div>

      <ul className="todo-list">
        {visibleTodos.map((todo, visibleIndex) => {
          const isEditing = editing?.id === todo.id;
          return (
            <li key={todo.id}>
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
                aria-label={todo.done ? `Mark "${todo.text}" as not done` : `Mark "${todo.text}" as done`}
              />
              {isEditing ? (
                <input
                  type="text"
                  autoFocus
                  value={editing.text}
                  onChange={(e: ChangeEvent<HTMLInputElement>) =>
                    setEditing((prev) => (prev ? { ...prev, text: e.target.value } : prev))
                  }
                  onBlur={commitEdit}
                  onKeyDown={handleEditKeyDown}
                />
              ) : (
                <span
                  className={todo.done ? "done" : undefined}
                  onDoubleClick={() => startEditing(todo)}
                  tabIndex={0}
                  role="button"
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      startEditing(todo);
                    }
                  }}
                >
                  {todo.text}
                </span>
              )}
              <button
                type="button"
                onMouseDown={preventBlur}
                onClick={() => startEditing(todo)}
                disabled={isEditing}
              >
                Edit
              </button>
              <button
                type="button"
                onMouseDown={preventBlur}
                onClick={() => moveTodo(todo.id, "up")}
                disabled={visibleIndex <= 0}
              >
                Move up
              </button>
              <button
                type="button"
                onMouseDown={preventBlur}
                onClick={() => moveTodo(todo.id, "down")}
                disabled={visibleIndex >= visibleTodos.length - 1}
              >
                Move down
              </button>
              <button type="button" onMouseDown={preventBlur} onClick={() => deleteTodo(todo.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>

      <p>{remainingCount} item(s) remaining</p>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  errors: Record<string, string>;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

async function fetchUser(id: string): Promise<User> {
  const response = await fetch(`/api/users/${encodeURIComponent(id)}`);
  if (!response.ok) {
    throw new Error(`Failed to load user ${id}: ${response.status}`);
  }
  const data: unknown = await response.json();
  if (!isUser(data)) {
    throw new Error(`Malformed user data for ${id}`);
  }
  if (data.id !== id) {
    throw new Error(`User data for ${id} did not match requested ID`);
  }
  return data;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(ids.length > 0);

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setErrors({});
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);

    Promise.allSettled(ids.map((id) => fetchUser(id))).then((results) => {
      if (cancelled) return;

      const nextProfiles: Record<string, User> = Object.create(null);
      const nextErrors: Record<string, string> = Object.create(null);

      results.forEach((result, index) => {
        const id = ids[index];
        if (result.status === "fulfilled") {
          nextProfiles[id] = result.value;
        } else {
          nextErrors[id] =
            result.reason instanceof Error ? result.reason.message : "Failed to load user";
        }
      });

      setProfiles(nextProfiles);
      setErrors(nextErrors);
      setLoading(false);
    });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [JSON.stringify(ids)]);

  return { profiles, loading, errors };
}

