struct Lap: Identifiable {
    let id = UUID()
    let number: Int
    let splitTime: TimeInterval
    let totalTime: TimeInterval
}

@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startInstant: ContinuousClock.Instant?
    private var accumulated: Duration = .zero

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startInstant = ContinuousClock.now
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.tick()
            }
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        accumulated = currentAccumulated()
        startInstant = nil
        elapsed = accumulated.timeInterval
    }

    func reset() {
        stop()
        elapsed = 0
        accumulated = .zero
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        elapsed = currentAccumulated().timeInterval
        let previousTotal = laps.last?.totalTime ?? 0
        laps.append(Lap(number: laps.count + 1, splitTime: elapsed - previousTotal, totalTime: elapsed))
    }

    private func tick() {
        elapsed = currentAccumulated().timeInterval
    }

    private func currentAccumulated() -> Duration {
        guard let startInstant else { return accumulated }
        return accumulated + startInstant.duration(to: ContinuousClock.now)
    }

    deinit {
        timer?.invalidate()
    }
}

private extension Duration {
    var timeInterval: TimeInterval {
        let (seconds, attoseconds) = components
        return Double(seconds) + Double(attoseconds) / 1e18
    }
}

enum StopwatchFormatter {
    static func format(_ time: TimeInterval) -> String {
        let totalHundredths = Int((time * 100).rounded())
        let minutes = totalHundredths / 6000
        let seconds = (totalHundredths / 100) % 60
        let hundredths = totalHundredths % 100
        return String(format: "%02d:%02d.%02d", minutes, seconds, hundredths)
    }
}

