struct Lap: Identifiable {
    let id = UUID()
    let elapsed: TimeInterval
}

@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startUptime: TimeInterval?
    private var accumulated: TimeInterval = 0

    deinit {
        timer?.invalidate()
    }

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startUptime = ProcessInfo.processInfo.systemUptime
        let timer = Timer(timeInterval: 0.01, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.tick()
            }
        }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func stop() {
        guard isRunning else { return }
        tick()
        isRunning = false
        timer?.invalidate()
        timer = nil
        accumulated = elapsed
        startUptime = nil
    }

    func reset() {
        stop()
        elapsed = 0
        accumulated = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        laps.insert(Lap(elapsed: elapsed), at: 0)
    }

    private func tick() {
        guard let startUptime else { return }
        elapsed = accumulated + (ProcessInfo.processInfo.systemUptime - startUptime)
    }

    static func format(_ interval: TimeInterval) -> String {
        let totalHundredths = Int((interval * 100).rounded())
        let minutes = totalHundredths / 6000
        let seconds = (totalHundredths / 100) % 60
        let hundredths = totalHundredths % 100
        return String(format: "%02d:%02d.%02d", minutes, seconds, hundredths)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 20) {
            Text(StopwatchViewModel.format(viewModel.elapsed))
                .font(.system(size: 48, weight: .medium, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    if viewModel.isRunning {
                        viewModel.stop()
                    } else {
                        viewModel.start()
                    }
                }
                Button("Lap") { viewModel.lap() }
                    .disabled(!viewModel.isRunning)
                Button("Reset") { viewModel.reset() }
                    .disabled(viewModel.isRunning)
            }

            List {
                ForEach(Array(viewModel.laps.enumerated()), id: \.element.id) { index, lap in
                    let lapNumber = viewModel.laps.count - index
                    let split = splitTime(at: index)
                    HStack {
                        Text("Lap \(lapNumber)")
                        Spacer()
                        Text(StopwatchViewModel.format(split))
                            .monospacedDigit()
                            .foregroundStyle(.secondary)
                        Text(StopwatchViewModel.format(lap.elapsed))
                            .monospacedDigit()
                    }
                }
            }
        }
        .padding()
        .frame(minWidth: 300, minHeight: 400)
    }

    private func splitTime(at index: Int) -> TimeInterval {
        let laps = viewModel.laps
        guard index < laps.count else { return 0 }
        let current = laps[index].elapsed
        let previous = index + 1 < laps.count ? laps[index + 1].elapsed : 0
        return current - previous
    }
}

import SwiftUI

enum ThemeChoice: String, CaseIterable, Identifiable, Equatable {
    case system
    case light
    case dark

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .system: return "System"
        case .light: return "Light"
        case .dark: return "Dark"
        }
    }
}

@MainActor
final class SettingsStore: ObservableObject {
    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    static let defaultRefreshInterval: TimeInterval = 60
    static let refreshIntervalRange: ClosedRange<TimeInterval> = 15...3600

    private static func sanitizedRefreshInterval(_ value: TimeInterval) -> TimeInterval {
        guard value.isFinite else { return defaultRefreshInterval }
        return min(max(value, refreshIntervalRange.lowerBound), refreshIntervalRange.upperBound)
    }

    @Published var displayName: String {
        didSet { persist { $0.set(displayName, forKey: Keys.displayName) } }
    }
    @Published var theme: ThemeChoice {
        didSet { persist { $0.set(theme.rawValue, forKey: Keys.theme) } }
    }
    @Published var notificationsEnabled: Bool {
        didSet { persist { $0.set(notificationsEnabled, forKey: Keys.notificationsEnabled) } }
    }
    @Published var refreshInterval: TimeInterval {
        didSet { persist { $0.set(refreshInterval, forKey: Keys.refreshInterval) } }
    }

    private let defaults: UserDefaults
    private var isApplyingExternalChange = false
    private var observer: NSObjectProtocol?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults

        displayName = defaults.string(forKey: Keys.displayName) ?? ""
        theme = ThemeChoice(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        refreshInterval = Self.sanitizedRefreshInterval(
            defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? Self.defaultRefreshInterval
        )

        observer = NotificationCenter.default.addObserver(
            forName: UserDefaults.didChangeNotification,
            object: defaults,
            queue: .main
        ) { [weak self] _ in
            // Safe: NotificationCenter delivers this on `queue: .main`.
            MainActor.assumeIsolated {
                self?.reloadFromDefaults()
            }
        }
    }

    deinit {
        if let observer {
            NotificationCenter.default.removeObserver(observer)
        }
    }

    // Only writes to UserDefaults when the change originated locally (from the UI),
    // not when we're re-applying a value we just read back from an external change.
    private func persist(_ write: (UserDefaults) -> Void) {
        guard !isApplyingExternalChange else { return }
        write(defaults)
    }

    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        if newDisplayName != displayName { displayName = newDisplayName }

        let newTheme = ThemeChoice(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        if newTheme != theme { theme = newTheme }

        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        if newNotificationsEnabled != notificationsEnabled { notificationsEnabled = newNotificationsEnabled }

        let newRefreshInterval = Self.sanitizedRefreshInterval(
            defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? Self.defaultRefreshInterval
        )
        if newRefreshInterval != refreshInterval { refreshInterval = newRefreshInterval }
    }
}

struct SettingsScreen: View {
    @ObservedObject var store: SettingsStore

    var body: some View {
        Form {
            Section("Profile") {
                TextField("Display Name", text: $store.displayName)
            }

            Section("Appearance") {
                Picker("Theme", selection: $store.theme) {
                    ForEach(ThemeChoice.allCases) { theme in
                        Text(theme.displayName).tag(theme)
                    }
                }
            }

            Section("Notifications") {
                Toggle("Enable Notifications", isOn: $store.notificationsEnabled)
            }

            Section("Refresh") {
                Stepper(value: $store.refreshInterval, in: SettingsStore.refreshIntervalRange, step: 15) {
                    Text("Refresh Interval: \(Int(store.refreshInterval))s")
                }
            }
        }
        .padding()
        .navigationTitle("Settings")
    }
}

import Foundation
import SwiftUI

/// Persists user preferences to `UserDefaults` and reloads whenever `UserDefaults`
/// reports a change within this process (e.g. another `SettingsStore` instance, or
/// any other code in the same process writing to the same suite). `UserDefaults
/// .didChangeNotification` is not posted across process boundaries, so writes made
/// by another process (e.g. via `defaults write`) are only picked up the next time
/// this process reads the key, not observed live.
final class SettingsStore: ObservableObject {
    enum Theme: String, CaseIterable, Identifiable, Equatable {
        case system, light, dark

        var id: String { rawValue }

        var displayName: String {
            switch self {
            case .system: return "System"
            case .light: return "Light"
            case .dark: return "Dark"
            }
        }
    }

    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    private static let refreshIntervalRange: ClosedRange<TimeInterval> = 15...600
    private static let defaultRefreshInterval: TimeInterval = 60

    private static func sanitizedRefreshInterval(_ raw: Double?) -> TimeInterval {
        guard let raw, raw.isFinite else { return defaultRefreshInterval }
        return min(max(raw, refreshIntervalRange.lowerBound), refreshIntervalRange.upperBound)
    }

    @Published var displayName: String {
        didSet {
            guard !isApplyingExternalChange else { return }
            defaults.set(displayName, forKey: Keys.displayName)
        }
    }

    @Published var theme: Theme {
        didSet {
            guard !isApplyingExternalChange else { return }
            defaults.set(theme.rawValue, forKey: Keys.theme)
        }
    }

    @Published var notificationsEnabled: Bool {
        didSet {
            guard !isApplyingExternalChange else { return }
            defaults.set(notificationsEnabled, forKey: Keys.notificationsEnabled)
        }
    }

    @Published var refreshInterval: TimeInterval {
        didSet {
            guard !isApplyingExternalChange else { return }
            defaults.set(refreshInterval, forKey: Keys.refreshInterval)
        }
    }

    private let defaults: UserDefaults
    private var notificationObserver: NSObjectProtocol?
    private var isApplyingExternalChange = false

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults

        displayName = defaults.string(forKey: Keys.displayName) ?? ""
        theme = Theme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        refreshInterval = Self.sanitizedRefreshInterval(defaults.object(forKey: Keys.refreshInterval) as? Double)

        notificationObserver = NotificationCenter.default.addObserver(
            forName: UserDefaults.didChangeNotification,
            object: defaults,
            queue: .main
        ) { [weak self] _ in
            self?.reloadFromDefaults()
        }
    }

    deinit {
        if let notificationObserver {
            NotificationCenter.default.removeObserver(notificationObserver)
        }
    }

    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        if newDisplayName != displayName { displayName = newDisplayName }

        let newTheme = Theme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        if newTheme != theme { theme = newTheme }

        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        if newNotificationsEnabled != notificationsEnabled { notificationsEnabled = newNotificationsEnabled }

        let newRefreshInterval = Self.sanitizedRefreshInterval(defaults.object(forKey: Keys.refreshInterval) as? Double)
        if newRefreshInterval != refreshInterval { refreshInterval = newRefreshInterval }
    }
}

