/// Shared in-memory cache so scrolling the grid doesn't re-download
/// thumbnails that are already on screen. Backed by `NSCache` so entries
/// are bounded and can be evicted under memory pressure.
actor ThumbnailCache {
    static let shared = ThumbnailCache()

    private let storage: NSCache<NSURL, CachedThumbnailBox> = {
        let cache = NSCache<NSURL, CachedThumbnailBox>()
        cache.countLimit = 200
        return cache
    }()

    func thumbnail(for url: URL) -> CachedThumbnail? {
        storage.object(forKey: url as NSURL)?.value
    }

    func store(_ thumbnail: CachedThumbnail, for url: URL) {
        storage.setObject(CachedThumbnailBox(thumbnail), forKey: url as NSURL)
    }
}

