/// Max pixel dimension to downsample decoded images to. Sized for a 100pt
/// cell at up to 3x scale so cached thumbnails stay small regardless of the
/// original photo's resolution.
private let thumbnailMaxPixelSize: CGFloat = 300

private struct ThumbnailCell: View {
    let url: URL

    @State private var thumbnail: CachedThumbnail?
    @State private var loadFailed = false

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color.secondary.opacity(0.2))

                if let thumbnail {
                    Image(platformImage: thumbnail.image)
                        .resizable()
                        .scaledToFill()
                } else if loadFailed {
                    Image(systemName: "photo")
                        .foregroundStyle(.secondary)
                } else {
                    ProgressView()
                }
            }
            .frame(width: 100, height: 100)
            .clipShape(RoundedRectangle(cornerRadius: 8))

            if let thumbnail {
                Text(thumbnail.downloadDate, format: .relative(presentation: .named))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            }
        }
        .task(id: url) {
            await load()
        }
    }

    private func load() async {
        loadFailed = false

        if let cached = await ThumbnailCache.shared.thumbnail(for: url) {
            thumbnail = cached
            return
        }

        do {
            let (data, response) = try await URLSession.shared.data(from: url)
            guard let httpResponse = response as? HTTPURLResponse,
                  (200...299).contains(httpResponse.statusCode) else {
                loadFailed = true
                return
            }
            guard let image = Self.downsampledImage(from: data, maxPixelSize: thumbnailMaxPixelSize) else {
                loadFailed = true
                return
            }

            let cached = CachedThumbnail(image: image, downloadDate: Date())
            await ThumbnailCache.shared.store(cached, for: url)
            thumbnail = cached
        } catch {
            loadFailed = true
        }
    }

    /// Decodes `data` directly to a downsampled image via ImageIO, avoiding
    /// ever materializing a full-resolution decode in memory.
    private static func downsampledImage(from data: Data, maxPixelSize: CGFloat) -> PlatformImage? {
        let sourceOptions = [kCGImageSourceShouldCache: false] as CFDictionary
        guard let source = CGImageSourceCreateWithData(data as CFData, sourceOptions) else {
            return nil
        }

        let thumbnailOptions = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceThumbnailMaxPixelSize: maxPixelSize
        ] as CFDictionary
        guard let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, thumbnailOptions) else {
            return nil
        }

        #if canImport(UIKit)
        return UIImage(cgImage: cgImage)
        #elseif canImport(AppKit)
        return NSImage(cgImage: cgImage, size: NSSize(width: cgImage.width, height: cgImage.height))
        #endif
    }
}

