private let thumbnailPointSize: CGFloat = 100

/// Decodes `data` directly to a bitmap no larger than `pointSize` (in `scale` pixels-per-point),
/// avoiding the memory and CPU cost of decoding the original full-resolution image.
private func downsampledImage(from data: Data, pointSize: CGFloat, scale: CGFloat) -> PlatformImage? {
    let maxPixelSize = pointSize * scale
    guard let source = CGImageSourceCreateWithData(data as CFData, [kCGImageSourceShouldCache: false] as CFDictionary) else {
        return nil
    }

    let options: [CFString: Any] = [
        kCGImageSourceCreateThumbnailFromImageAlways: true,
        kCGImageSourceCreateThumbnailWithTransform: true,
        kCGImageSourceShouldCacheImmediately: true,
        kCGImageSourceThumbnailMaxPixelSize: maxPixelSize
    ]
    guard let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else {
        return nil
    }

    #if canImport(AppKit)
    return NSImage(cgImage: cgImage, size: CGSize(width: cgImage.width, height: cgImage.height))
    #elseif canImport(UIKit)
    return UIImage(cgImage: cgImage, scale: scale, orientation: .up)
    #endif
}

