private struct ThumbnailCell: View {
    let photo: Photo

    @State private var image: PlatformImage?
    @State private var isLoading = false
    @Environment(\.displayScale) private var displayScale

    private static let relativeFormatter: RelativeDateTimeFormatter = {
        let formatter = RelativeDateTimeFormatter()
        formatter.unitsStyle = .abbreviated
        return formatter
    }()

    var body: some View {
        VStack(spacing: 4) {
            thumbnailContent
                .frame(width: 100, height: 100)
                .clipped()

            Text(Self.relativeFormatter.localizedString(for: photo.downloadDate, relativeTo: Date()))
                .font(.caption2)
                .foregroundStyle(.secondary)
        }
        .task(id: photo.url) {
            await loadImage(for: photo.url)
        }
    }

    @ViewBuilder
    private var thumbnailContent: some View {
        if let image {
            #if canImport(AppKit)
            Image(nsImage: image)
                .resizable()
                .aspectRatio(contentMode: .fill)
            #elseif canImport(UIKit)
            Image(uiImage: image)
                .resizable()
                .aspectRatio(contentMode: .fill)
            #endif
        } else {
            ZStack {
                Rectangle().fill(.gray.opacity(0.2))
                if isLoading {
                    ProgressView()
                }
            }
        }
    }

    private func loadImage(for url: URL) async {
        // Reset state up front so a reused cell doesn't keep showing the previous
        // URL's image (or lack thereof) while this URL loads or if it fails.
        image = nil

        if let cached = ThumbnailImageCache.shared.image(for: url) {
            image = cached
            return
        }

        isLoading = true
        defer {
            // Skip the reset if this task was cancelled (e.g. photo.url changed):
            // otherwise this stale task's defer can fire after the replacement
            // task already set isLoading = true, hiding its spinner.
            if !Task.isCancelled {
                isLoading = false
            }
        }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            guard !Task.isCancelled else { return }
            guard let loaded = downsampledImage(from: data, pointSize: thumbnailPointSize, scale: displayScale) else { return }
            ThumbnailImageCache.shared.insert(loaded, for: url)
            image = loaded
        } catch {
            // Network failure or cancellation: leave the placeholder in place.
        }
    }
}

