/// Serializes access to a `LegacyUploader`, which only has a single slot for
/// `onProgress`/`onFinish`, so overlapping `upload(file:)` calls can't stomp on
/// each other's callbacks.
private actor UploadTurnstile {
    private var isBusy = false
    private var waiters: [CheckedContinuation<Void, Never>] = []

    func acquire() async {
        if !isBusy {
            isBusy = true
            return
        }
        await withCheckedContinuation { waiters.append($0) }
    }

    func release() {
        if let next = waiters.first {
            waiters.removeFirst()
            next.resume()
        } else {
            isBusy = false
        }
    }
}

final class LegacyUploaderBridge {
    private let uploader = LegacyUploader()
    private let progressContinuation: AsyncStream<Double>.Continuation
    private let turnstile = UploadTurnstile()

    /// Emits progress values reported by the legacy uploader across all uploads
    /// made through this bridge.
    let progress: AsyncStream<Double>

    init() {
        var continuation: AsyncStream<Double>.Continuation!
        self.progress = AsyncStream { continuation = $0 }
        self.progressContinuation = continuation
    }

    deinit {
        progressContinuation.finish()
    }

    func upload(file: URL) async throws {
        await turnstile.acquire()
        do {
            try await performUpload(file: file)
        } catch {
            await turnstile.release()
            throw error
        }
        await turnstile.release()
    }

    private func performUpload(file: URL) async throws {
        let resumeLock = NSLock()
        var hasResumed = false

        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            uploader.onProgress = { [progressContinuation] value in
                progressContinuation.yield(value)
            }
            uploader.onFinish = { error in
                resumeLock.lock()
                let alreadyResumed = hasResumed
                hasResumed = true
                resumeLock.unlock()
                guard !alreadyResumed else { return }

                if let error = error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume()
                }
            }
            uploader.start(file: file)
        }
    }
}

