/// In-memory cache shared across all thumbnails so scrolling back into
/// view doesn't trigger a re-download. Isolated as an actor so concurrent
/// loads from multiple thumbnails can't race on the underlying cache.
actor ImageCache {
    static let shared = ImageCache()

    private let cache = NSCache<NSURL, PlatformImage>()
    private var inFlightTasks: [URL: Task<PlatformImage?, Never>] = [:]

    private init() {}

    /// Returns the cached image, awaiting an in-flight download for `url` if
    /// one is already running instead of starting a duplicate download.
    func image(for url: URL) async -> PlatformImage? {
        if let cached = cache.object(forKey: url as NSURL) {
            return cached
        }

        if let existing = inFlightTasks[url] {
            return await existing.value
        }

        let task = Task<PlatformImage?, Never> {
            guard let (data, _) = try? await URLSession.shared.data(from: url) else {
                return nil
            }
            // Decode off the calling actor (and off the main actor for
            // callers on it) since constructing the platform image from
            // raw data can be expensive.
            return await Task.detached(priority: .userInitiated) {
                PlatformImage(data: data)
            }.value
        }
        inFlightTasks[url] = task

        let result = await task.value
        inFlightTasks[url] = nil
        if let result {
            cache.setObject(result, forKey: url as NSURL)
        }
        return result
    }
}

private struct ThumbnailView: View {
    let url: URL

    @State private var image: PlatformImage?
    @State private var loadFailed = false
    @State private var retryToken = 0

    var body: some View {
        ZStack {
            if let image {
                platformImage(image)
                    .resizable()
                    .aspectRatio(contentMode: .fill)
            } else if loadFailed {
                Rectangle()
                    .fill(Color.secondary.opacity(0.2))
                    .overlay(
                        Button {
                            retryToken += 1
                        } label: {
                            Image(systemName: "arrow.clockwise")
                        }
                        .buttonStyle(.plain)
                    )
            } else {
                Rectangle()
                    .fill(Color.secondary.opacity(0.2))
                    .overlay(ProgressView())
            }
        }
        // Reset local state as soon as the URL (or a retry) invalidates the
        // previous load, so a cancelled task can't publish a stale image.
        .task(id: "\(url.absoluteString)#\(retryToken)") {
            image = nil
            loadFailed = false
            await loadImage()
        }
    }

    @ViewBuilder
    private func platformImage(_ image: PlatformImage) -> Image {
        #if canImport(UIKit)
        Image(uiImage: image)
        #else
        Image(nsImage: image)
        #endif
    }

    @MainActor
    private func loadImage() async {
        let loaded = await ImageCache.shared.image(for: url)

        // The task may have been cancelled (URL changed, view disappeared)
        // while we were suspended; don't publish results for a stale load.
        guard !Task.isCancelled else { return }

        guard let loaded else {
            loadFailed = true
            return
        }
        image = loaded
    }
}

