import Foundation
import SwiftUI

struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []

    private let url = URL(string: "wss://chat.example.com/room")!
    private let session = URLSession(configuration: .default)
    private var task: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var generation = 0
    private var reconnectWorkItem: DispatchWorkItem?

    func connect() {
        task?.cancel()
        reconnectWorkItem?.cancel()
        reconnectWorkItem = nil
        generation += 1
        let currentGeneration = generation

        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()
        listen(generation: currentGeneration)
    }

    func disconnect() {
        generation += 1
        reconnectWorkItem?.cancel()
        reconnectWorkItem = nil
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }

    @discardableResult
    func send(text: String) -> Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return true }
        guard let task else { return false }
        let outgoing = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(outgoing) else { return true }
        let currentGeneration = generation
        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                self?.scheduleReconnect(generation: currentGeneration)
            }
        }
        return true
    }

    private func listen(generation: Int) {
        task?.receive { [weak self] result in
            Task { @MainActor in
                guard let self, self.generation == generation else { return }
                switch result {
                case .success(let message):
                    self.reconnectDelay = 1
                    self.handle(message)
                    self.listen(generation: generation)
                case .failure:
                    self.scheduleReconnect(generation: generation)
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = Data(text.utf8)
        @unknown default:
            return
        }
        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
    }

    private func scheduleReconnect(generation: Int) {
        guard generation == self.generation, reconnectWorkItem == nil else { return }
        task?.cancel()
        task = nil
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        let workItem = DispatchWorkItem { [weak self] in
            self?.reconnectWorkItem = nil
            self?.connect()
        }
        reconnectWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: workItem)
    }
}

