import Foundation
import SwiftUI

struct ChatMessage: Identifiable, Codable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatViewModel: ObservableObject {
    @Published var messages: [ChatMessage] = []
    @Published var draft: String = ""
    @Published private(set) var isConnected: Bool = false

    private let session: URLSession
    private let url: URL = {
        guard let url = URL(string: "wss://chat.example.com/room") else {
            preconditionFailure("Invalid chat room URL")
        }
        return url
    }()
    private var task: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    /// How long a connection must stay open before we consider it proven and reset the backoff.
    private let stableConnectionDelay: TimeInterval = 2
    private var isStopped = false
    /// Identifies the current socket so callbacks from a cancelled/replaced one are ignored.
    private var connectionID = UUID()
    private var reconnectTask: Task<Void, Never>?

    init(session: URLSession = .shared) {
        self.session = session
    }

    func start() {
        isStopped = false
        connect()
    }

    func stop() {
        isStopped = true
        connectionID = UUID()
        reconnectTask?.cancel()
        reconnectTask = nil
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
        isConnected = false
    }

    func send() {
        let trimmed = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task else { return }

        let outgoing = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(outgoing) else { return }

        draft = ""
        let generation = connectionID
        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                guard let self, self.connectionID == generation else { return }
                self.scheduleReconnect()
            }
        }
    }

    private func connect() {
        reconnectTask?.cancel()
        reconnectTask = nil

        let generation = UUID()
        connectionID = generation

        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()
        isConnected = true
        receiveNext(generation: generation)

        let stableDelay = stableConnectionDelay
        Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(stableDelay * 1_000_000_000))
            guard let self, self.connectionID == generation else { return }
            self.reconnectDelay = 1
        }
    }

    private func receiveNext(generation: UUID) {
        guard let task else { return }
        task.receive { [weak self] result in
            Task { @MainActor in
                guard let self, self.connectionID == generation else { return }
                switch result {
                case .success(let message):
                    self.handle(message)
                    self.receiveNext(generation: generation)
                case .failure:
                    self.scheduleReconnect()
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = Data(text.utf8)
        @unknown default:
            return
        }

        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
    }

    private func scheduleReconnect() {
        guard !isStopped else { return }
        task = nil
        isConnected = false

        reconnectTask?.cancel()

        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        let generation = connectionID

        reconnectTask = Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard let self, !Task.isCancelled, !self.isStopped, self.connectionID == generation else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var viewModel = ChatViewModel()

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(viewModel.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .padding()
                }
                .onChange(of: viewModel.messages) { _ in
                    scrollToBottom(proxy: proxy)
                }
                .onAppear {
                    scrollToBottom(proxy: proxy)
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $viewModel.draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit { viewModel.send() }
                Button("Send", action: viewModel.send)
                    .disabled(
                        viewModel.draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                            || !viewModel.isConnected
                    )
            }
            .padding()
        }
        .onAppear { viewModel.start() }
        .onDisappear { viewModel.stop() }
    }

    private func scrollToBottom(proxy: ScrollViewProxy) {
        guard let last = viewModel.messages.last else { return }
        withAnimation {
            proxy.scrollTo(last.id, anchor: .bottom)
        }
    }
}

import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.name === "string" &&
    typeof candidate.email === "string"
  );
}

function parseUsers(data: unknown): User[] {
  if (!Array.isArray(data)) return [];
  return data.filter(isUser);
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    if (query === "") {
      setDebouncedQuery("");
      return;
    }
    const timer = setTimeout(() => setDebouncedQuery(query), DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  useEffect(() => {
    if (!debouncedQuery) {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json();
      })
      .then((data: unknown) => {
        setUsers(parseUsers(data));
      })
      .catch((err: unknown) => {
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
        setUsers([]);
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      });

    return () => controller.abort();
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label htmlFor="sort-field">Sort by: </label>
        <select
          id="sort-field"
          value={sortField}
          onChange={(e) => setSortField(e.target.value as SortField)}
        >
          <option value="name">Name</option>
          <option value="email">Email</option>
        </select>
      </div>

      {loading && <div role="status">Loading...</div>}
      {error && <div role="alert">Error: {error}</div>}

      {!loading && !error && debouncedQuery && (
        <>
          <div>{sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}</div>
          <ul>
            {sortedUsers.map((user) => (
              <li key={user.id}>
                <span>{user.name}</span> — <span>{user.email}</span>
              </li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}

import Foundation
import os

// MARK: - Legacy SDK (callback-based)

private let stubGeocodeDelay: TimeInterval = 0.1
private let stubUploadStepCount = 5
private let stubUploadStepDelay: TimeInterval = 0.05

/// Lets a caller stop a pending legacy callback from firing once cancelled.
final class LegacyCancellationToken: @unchecked Sendable {
    private let lock = NSLock()
    private var _isCancelled = false

    var isCancelled: Bool {
        lock.lock()
        defer { lock.unlock() }
        return _isCancelled
    }

    func cancel() {
        lock.lock()
        _isCancelled = true
        lock.unlock()
    }
}

final class LegacyGeocoder {
    @discardableResult
    func geocode(_ address: String, completion: @escaping (Result<(Double, Double), Error>) -> Void) -> LegacyCancellationToken {
        let token = LegacyCancellationToken()
        DispatchQueue.global().asyncAfter(deadline: .now() + stubGeocodeDelay) {
            guard !token.isCancelled else { return }
            completion(.success((37.7749, -122.4194)))
        }
        return token
    }
}

final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    @discardableResult
    func start(file: URL) -> LegacyCancellationToken {
        let token = LegacyCancellationToken()
        for step in 1...stubUploadStepCount {
            DispatchQueue.global().asyncAfter(deadline: .now() + Double(step) * stubUploadStepDelay) {
                guard !token.isCancelled else { return }
                self.onProgress?(Double(step) / Double(stubUploadStepCount))
                if step == stubUploadStepCount {
                    self.onFinish?(nil)
                }
            }
        }
        return token
    }
}

// MARK: - Modern async/await bridge

enum LegacyBridgeError: Error {
    case uploadAlreadyStarted
}

/// Bridges a single callback-based legacy call to a checked continuation, guarding
/// against the completion firing more than once and against task cancellation racing
/// with that completion.
private final class CancellableCallState<T>: @unchecked Sendable {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<T, Error>?
    private var cancelToken: LegacyCancellationToken?
    private var isCancelled = false

    func setContinuation(_ continuation: CheckedContinuation<T, Error>) {
        lock.lock()
        if isCancelled {
            lock.unlock()
            continuation.resume(throwing: CancellationError())
            return
        }
        self.continuation = continuation
        lock.unlock()
    }

    func setCancelToken(_ token: LegacyCancellationToken) {
        lock.lock()
        if isCancelled {
            lock.unlock()
            token.cancel()
            return
        }
        cancelToken = token
        lock.unlock()
    }

    func resume(with result: Result<T, Error>) {
        lock.lock()
        guard let continuation else {
            lock.unlock()
            return
        }
        self.continuation = nil
        lock.unlock()
        continuation.resume(with: result)
    }

    func cancel() {
        lock.lock()
        isCancelled = true
        let continuation = self.continuation
        self.continuation = nil
        let token = cancelToken
        lock.unlock()
        token?.cancel()
        continuation?.resume(throwing: CancellationError())
    }
}

final class LegacyGeocoderBridge {
    private let geocoder = LegacyGeocoder()

    func geocode(_ address: String) async throws -> (Double, Double) {
        let state = CancellableCallState<(Double, Double)>()
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                state.setContinuation(continuation)
                let token = geocoder.geocode(address) { result in
                    state.resume(with: result)
                }
                state.setCancelToken(token)
            }
        } onCancel: {
            state.cancel()
        }
    }
}

final class LegacyUploaderBridge {
    private let uploader = LegacyUploader()
    private let progressContinuation: AsyncStream<Double>.Continuation
    private let hasStarted = OSAllocatedUnfairLock(initialState: false)

    /// Emits progress values as the upload runs; finishes when the upload completes or fails.
    let progress: AsyncStream<Double>

    init() {
        let (stream, continuation) = AsyncStream<Double>.makeStream(of: Double.self)
        progress = stream
        progressContinuation = continuation
    }

    func upload(file: URL) async throws {
        let alreadyStarted = hasStarted.withLock { hasStarted -> Bool in
            defer { hasStarted = true }
            return hasStarted
        }
        if alreadyStarted {
            throw LegacyBridgeError.uploadAlreadyStarted
        }

        let state = CancellableCallState<Void>()
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                state.setContinuation(continuation)
                uploader.onProgress = { [progressContinuation] value in
                    progressContinuation.yield(value)
                }
                uploader.onFinish = { [progressContinuation] error in
                    progressContinuation.finish()
                    if let error {
                        state.resume(with: .failure(error))
                    } else {
                        state.resume(with: .success(()))
                    }
                }
                let token = uploader.start(file: file)
                state.setCancelToken(token)
            }
        } onCancel: {
            state.cancel()
            progressContinuation.finish()
        }
    }
}

import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const REFRESH_INTERVAL_MS = 10_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    Number.isFinite(candidate.value) &&
    typeof candidate.unit === "string"
  );
}

function parseMetrics(payload: unknown): Metric[] {
  if (!Array.isArray(payload) || !payload.every(isMetric)) {
    throw new Error("Received malformed metrics data");
  }
  return payload;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [secondsAgo, setSecondsAgo] = useState(0);
  const previousValuesRef = useRef<Map<string, number>>(new Map());
  const requestIdRef = useRef(0);

  useEffect(() => {
    let cancelled = false;

    const fetchMetrics = async () => {
      const requestId = ++requestIdRef.current;
      try {
        const response = await fetch("/api/metrics");
        if (!response.ok) {
          throw new Error(`Request failed with status ${response.status}`);
        }
        const data = parseMetrics(await response.json());
        if (cancelled || requestId !== requestIdRef.current) return;

        const previousValues = previousValuesRef.current;
        const nextChanged = new Set<string>();
        for (const metric of data) {
          const previous = previousValues.get(metric.name);
          if (previous !== undefined && previous !== metric.value) {
            nextChanged.add(metric.name);
          }
        }

        previousValuesRef.current = new Map(
          data.map((metric) => [metric.name, metric.value])
        );

        setMetrics(data);
        setChangedNames(nextChanged);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (!cancelled && requestId === requestIdRef.current) {
          setError(err instanceof Error ? err.message : "Failed to load metrics");
        }
      }
    };

    let intervalId: ReturnType<typeof setInterval> | null = null;

    const startPolling = () => {
      if (intervalId !== null) return;
      fetchMetrics();
      intervalId = setInterval(fetchMetrics, REFRESH_INTERVAL_MS);
    };

    const stopPolling = () => {
      if (intervalId !== null) {
        clearInterval(intervalId);
        intervalId = null;
      }
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        startPolling();
      }
    };

    if (!document.hidden) {
      startPolling();
    }

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      stopPolling();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    if (!lastUpdated) return;

    const tick = () => {
      setSecondsAgo(Math.max(0, Math.floor((Date.now() - lastUpdated.getTime()) / 1000)));
    };

    tick();
    const timerId = setInterval(tick, 1000);
    return () => clearInterval(timerId);
  }, [lastUpdated]);

  return (
    <div className="metrics-panel">
      <div className="metrics-panel-header">
        <h2>Metrics</h2>
        <span className="metrics-panel-updated">
          {lastUpdated ? `Last updated ${secondsAgo} second${secondsAgo === 1 ? "" : "s"} ago` : "Loading…"}
        </span>
      </div>
      {error && <div className="metrics-panel-error">{error}</div>}
      <ul className="metrics-panel-list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={changedNames.has(metric.name) ? "metrics-panel-item changed" : "metrics-panel-item"}
          >
            <span className="metrics-panel-name">{metric.name}</span>
            <span className="metrics-panel-value">
              {metric.value} {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

