import Foundation
import SwiftUI

struct ChatMessage: Codable, Identifiable, Hashable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: NSObject, ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []

    private let url = URL(string: "wss://chat.example.com/room")!
    private var session: URLSession!
    private var task: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var shouldReconnect = true
    private let maxRetainedMessages = 500

    /// Bumped on every connect/disconnect/stop so callbacks and timers from a
    /// superseded connection attempt can recognize they're stale and no-op.
    private var generation = 0

    override init() {
        super.init()
        session = URLSession(configuration: .default)
    }

    func start() {
        shouldReconnect = true
        connect()
    }

    func stop() {
        shouldReconnect = false
        generation += 1
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }

    @discardableResult
    func send(text: String) -> Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }
        guard let task, task.state == .running else { return false }
        let message = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(message) else { return false }
        let generation = self.generation
        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                guard let self, self.generation == generation else { return }
                self.handleDisconnect(generation: generation)
            }
        }
        return true
    }

    private func connect() {
        generation += 1
        let generation = self.generation
        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()
        listen(on: task, generation: generation)
    }

    private func listen(on task: URLSessionWebSocketTask, generation: Int) {
        task.receive { [weak self] result in
            guard let self else { return }
            Task { @MainActor in
                guard self.generation == generation else { return }
                switch result {
                case .failure:
                    self.handleDisconnect(generation: generation)
                case .success(let message):
                    self.reconnectDelay = 1
                    self.handle(message)
                    self.listen(on: task, generation: generation)
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let d):
            data = d
        case .string(let s):
            data = Data(s.utf8)
        @unknown default:
            return
        }
        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
        if messages.count > maxRetainedMessages {
            messages.removeFirst(messages.count - maxRetainedMessages)
        }
    }

    private func handleDisconnect(generation: Int) {
        guard generation == self.generation else { return }
        self.generation += 1
        task = nil
        guard shouldReconnect else { return }
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        let nextGeneration = self.generation
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            guard let self, self.shouldReconnect, self.generation == nextGeneration else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var connection = ChatConnection()
    @State private var draft = ""

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(connection.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .padding(.horizontal)
                        }
                    }
                    .padding(.vertical, 8)
                }
                .onChange(of: connection.messages) { messages in
                    guard let last = messages.last else { return }
                    withAnimation {
                        proxy.scrollTo(last.id, anchor: .bottom)
                    }
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit(sendDraft)
                Button("Send", action: sendDraft)
                    .disabled(draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { connection.start() }
        .onDisappear { connection.stop() }
    }

    private func sendDraft() {
        guard connection.send(text: draft) else { return }
        draft = ""
    }
}

import Foundation

// MARK: - Legacy callback-based SDK (stubs)

final class LegacyGeocoder {
    private static let simulatedDelay: TimeInterval = 0.1

    func geocode(_ address: String, completion: @escaping (Result<(Double, Double), Error>) -> Void) {
        DispatchQueue.global().asyncAfter(deadline: .now() + Self.simulatedDelay) {
            guard !address.isEmpty else {
                completion(.failure(LegacyBridgeError.invalidAddress))
                return
            }
            completion(.success((37.7749, -122.4194)))
        }
    }
}

final class LegacyUploader {
    private static let progressSteps = 5
    private static let stepDelay: TimeInterval = 0.05

    private let lock = NSLock()
    private var _onProgress: ((Double) -> Void)?
    private var _onFinish: ((Error?) -> Void)?

    // `onProgress`/`onFinish` are written from whichever thread calls this setter
    // and read back from DispatchQueue.global() blocks scheduled by `start`, so
    // access is guarded by `lock` to avoid an unsynchronized cross-thread race.
    func setCallbacks(onProgress: @escaping (Double) -> Void, onFinish: @escaping (Error?) -> Void) {
        lock.lock()
        _onProgress = onProgress
        _onFinish = onFinish
        lock.unlock()
    }

    func start(file: URL) {
        for step in 1...Self.progressSteps {
            DispatchQueue.global().asyncAfter(deadline: .now() + Double(step) * Self.stepDelay) {
                self.lock.lock()
                let onProgress = self._onProgress
                let onFinish = self._onFinish
                self.lock.unlock()
                onProgress?(Double(step) / Double(Self.progressSteps))
                if step == Self.progressSteps {
                    onFinish?(nil)
                }
            }
        }
    }
}

enum LegacyBridgeError: Error {
    case invalidAddress
    case uploadAlreadyInProgress
}

// MARK: - Modern async/await wrapper
//
// `LegacyGeocoder`/`LegacyUploader` expose no cancel API, so a cancelled Task
// can't stop the underlying legacy work — it just keeps running in the
// background and its result is discarded. `ContinuationBox` still lets a
// cancelled Task stop *waiting* immediately (resuming with CancellationError)
// instead of hanging until the legacy callback eventually fires, while
// guaranteeing the continuation is resumed exactly once even if cancellation
// and the legacy callback race.
private final class ContinuationBox<T> {
    private var continuation: CheckedContinuation<T, Error>?
    private var pendingError: Error?
    private var resumed = false
    private let lock = NSLock()

    func set(_ continuation: CheckedContinuation<T, Error>) {
        lock.lock()
        defer { lock.unlock() }
        guard !resumed else {
            if let pendingError {
                continuation.resume(throwing: pendingError)
            }
            return
        }
        self.continuation = continuation
    }

    func resume(with result: Result<T, Error>) {
        lock.lock()
        defer { lock.unlock() }
        guard !resumed else { return }
        resumed = true
        if let continuation {
            continuation.resume(with: result)
            self.continuation = nil
        } else if case .failure(let error) = result {
            pendingError = error
        }
    }
}

actor LegacyBridge {
    private let geocoder = LegacyGeocoder()
    private let uploader = LegacyUploader()

    private var progressContinuation: AsyncStream<Double>.Continuation?
    private lazy var progressStream: AsyncStream<Double> = AsyncStream { self.progressContinuation = $0 }
    private var isUploading = false

    /// Emits upload progress (0.0...1.0) reported by `upload(file:)`.
    var uploadProgress: AsyncStream<Double> {
        progressStream
    }

    func geocode(_ address: String) async throws -> (Double, Double) {
        let box = ContinuationBox<(Double, Double)>()
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                box.set(continuation)
                geocoder.geocode(address) { result in
                    box.resume(with: result)
                }
            }
        } onCancel: {
            box.resume(with: .failure(CancellationError()))
        }
    }

    func upload(file: URL) async throws {
        guard !isUploading else {
            throw LegacyBridgeError.uploadAlreadyInProgress
        }
        // `isUploading` is cleared from `finishUpload()`, which only runs once the
        // legacy uploader actually calls `onFinish`. The legacy SDK has no cancel
        // API, so if the awaiting Task is cancelled the upload keeps running in the
        // background; clearing the flag here (e.g. via `defer`) would let a second
        // `upload(file:)` start while the first is still in flight, and both would
        // race to overwrite the shared `uploader` callbacks.
        isUploading = true

        // Force the lazy stream to materialize its continuation now, while still
        // actor-isolated, so it can be captured and yielded to synchronously below.
        _ = progressStream
        let progressContinuation = self.progressContinuation

        let box = ContinuationBox<Void>()
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                box.set(continuation)
                uploader.setCallbacks(
                    onProgress: { progress in
                        // Yielding directly (rather than hopping through a new Task per
                        // callback) preserves the order the legacy uploader calls back in;
                        // routing each event through an independent unstructured Task would
                        // not guarantee that ordering.
                        progressContinuation?.yield(progress)
                    },
                    onFinish: { [weak self] error in
                        box.resume(with: error.map { .failure($0) } ?? .success(()))
                        Task { await self?.finishUpload() }
                    }
                )
                uploader.start(file: file)
            }
        } onCancel: {
            box.resume(with: .failure(CancellationError()))
        }
    }

    private func finishUpload() {
        isUploading = false
    }
}

import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const SORT_FIELDS: SortField[] = ["name", "email"];

function isSortField(value: string): value is SortField {
  return (SORT_FIELDS as string[]).includes(value);
}

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const record = value as Record<string, unknown>;
  return (
    typeof record.id === "string" &&
    typeof record.name === "string" &&
    typeof record.email === "string"
  );
}

function parseUsers(value: unknown): User[] {
  if (!Array.isArray(value)) {
    throw new Error("Malformed response: expected an array of users");
  }
  if (!value.every(isUser)) {
    throw new Error("Malformed response: unexpected user shape");
  }
  return value;
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  useEffect(() => {
    if (!debouncedQuery) {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    let isCurrent = true;
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json();
      })
      .then((json: unknown) => {
        if (!isCurrent) return;
        setUsers(parseUsers(json));
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (!isCurrent) return;
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
        setUsers([]);
        setLoading(false);
      });

    return () => {
      isCurrent = false;
      controller.abort();
    };
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  const isPending = query !== debouncedQuery;

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label>
          Sort by:{" "}
          <select
            value={sortField}
            onChange={(e) => {
              const { value } = e.target;
              if (isSortField(value)) setSortField(value);
            }}
          >
            <option value="name">Name</option>
            <option value="email">Email</option>
          </select>
        </label>
      </div>

      {(loading || isPending) && <p>Loading...</p>}
      {error && <p role="alert">Error: {error}</p>}
      {!loading && !isPending && !error && debouncedQuery && (
        <p>
          {sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}
        </p>
      )}

      <ul>
        {!isPending &&
          sortedUsers.map((user) => (
            <li key={user.id}>
              {user.name} ({user.email})
            </li>
          ))}
      </ul>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    Number.isFinite(candidate.value) &&
    typeof candidate.unit === "string"
  );
}

function hasDuplicateNames(metrics: Metric[]): boolean {
  const seen = new Set<string>();
  for (const metric of metrics) {
    if (seen.has(metric.name)) return true;
    seen.add(metric.name);
  }
  return false;
}

async function fetchMetrics(signal: AbortSignal): Promise<Metric[]> {
  const res = await fetch("/api/metrics", { signal });
  if (!res.ok) {
    throw new Error(`Failed to load metrics: ${res.status} ${res.statusText}`);
  }
  const body: unknown = await res.json();
  if (!Array.isArray(body) || !body.every(isMetric) || hasDuplicateNames(body)) {
    throw new Error("Metrics response had an unexpected shape");
  }
  return body;
}

function useTick(intervalMs: number): number {
  const [, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick((t) => t + 1), intervalMs);
    return () => clearInterval(id);
  }, [intervalMs]);
  return Date.now();
}

function formatSecondsAgo(lastUpdated: Date | null, now: number): string {
  if (!lastUpdated) return "never";
  const seconds = Math.max(0, Math.round((now - lastUpdated.getTime()) / 1000));
  if (seconds === 0) return "just now";
  if (seconds === 1) return "1 second ago";
  return `${seconds} seconds ago`;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<ReadonlySet<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const previousValuesRef = useRef<Map<string, number>>(new Map());
  const now = useTick(1000);

  useEffect(() => {
    let cancelled = false;
    let activeController: AbortController | null = null;
    let requestId = 0;

    async function refresh() {
      if (document.hidden) return;

      // Abort any in-flight request so overlapping refreshes can't resolve
      // out of order and overwrite newer data with stale data.
      activeController?.abort();
      const controller = new AbortController();
      activeController = controller;
      const currentRequestId = ++requestId;

      try {
        const fetchedMetrics = await fetchMetrics(controller.signal);
        if (cancelled || currentRequestId !== requestId) return;

        const previousValues = previousValuesRef.current;
        const nextChanged = new Set<string>();
        for (const metric of fetchedMetrics) {
          const previous = previousValues.get(metric.name);
          if (previous !== undefined && previous !== metric.value) {
            nextChanged.add(metric.name);
          }
        }
        previousValuesRef.current = new Map(fetchedMetrics.map((m) => [m.name, m.value]));

        setMetrics(fetchedMetrics);
        setChangedNames(nextChanged);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (cancelled || currentRequestId !== requestId || (err instanceof DOMException && err.name === "AbortError")) return;
        setError(err instanceof Error ? err.message : "Failed to load metrics");
      } finally {
        if (!cancelled && currentRequestId === requestId) setLoading(false);
      }
    }

    void refresh();
    const intervalId = setInterval(() => void refresh(), POLL_INTERVAL_MS);

    function handleVisibilityChange() {
      if (!document.hidden) void refresh();
    }
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      activeController?.abort();
      clearInterval(intervalId);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  return (
    <div className="metrics-panel">
      <header className="metrics-panel__header">
        <h2>Metrics</h2>
        <span className="metrics-panel__updated">
          last updated {formatSecondsAgo(lastUpdated, now)}
        </span>
      </header>

      {error && <p className="metrics-panel__error">{error}</p>}
      {loading && !error && <p className="metrics-panel__loading">Loading metrics…</p>}

      {!loading && !error && (
        <ul className="metrics-panel__list">
          {metrics.map((metric) => (
            <li
              key={metric.name}
              className={
                changedNames.has(metric.name)
                  ? "metrics-panel__item metrics-panel__item--changed"
                  : "metrics-panel__item"
              }
            >
              <span className="metrics-panel__name">{metric.name}</span>
              <span className="metrics-panel__value">
                {metric.value}
                {metric.unit}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

import { useState, FormEvent } from "react";

type FormFields = "name" | "email" | "password" | "confirmPassword" | "acceptTerms";

type FormState = {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
};

type FieldErrors = Partial<Record<FormFields, string>>;

const FORM_FIELDS: FormFields[] = ["name", "email", "password", "confirmPassword", "acceptTerms"];

function sanitizeFieldErrors(errors: unknown): FieldErrors {
  if (typeof errors !== "object" || errors === null) {
    return {};
  }

  const sanitized: FieldErrors = {};
  for (const field of FORM_FIELDS) {
    const value = (errors as Record<string, unknown>)[field];
    if (typeof value === "string" && value) {
      sanitized[field] = value;
    }
  }
  return sanitized;
}

const initialState: FormState = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(form: FormState): FieldErrors {
  const errors: FieldErrors = {};

  if (!form.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!form.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(form.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!form.password) {
    errors.password = "Password is required.";
  } else if (form.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!form.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (form.confirmPassword !== form.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!form.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

type SignupResponse = {
  id: string;
};

type SignupErrorResponse = {
  errors?: Record<string, string>;
};

export default function SignupForm() {
  const [form, setForm] = useState<FormState>(initialState);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);

  function updateField<K extends keyof FormState>(field: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({
      ...prev,
      [field]: undefined,
      ...(field === "password" ? { confirmPassword: undefined } : {}),
    }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (submitting) {
      return;
    }

    const clientErrors = validate(form);
    if (Object.keys(clientErrors).length > 0) {
      setErrors(clientErrors);
      return;
    }

    setSubmitting(true);
    setSubmitError(null);

    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: form.name,
          email: form.email,
          password: form.password,
          confirmPassword: form.confirmPassword,
          acceptTerms: form.acceptTerms,
        }),
      });

      if (!response.ok) {
        const data = (await response.json().catch(() => ({}))) as SignupErrorResponse;
        const fieldErrors = sanitizeFieldErrors(data.errors);
        if (Object.keys(fieldErrors).length > 0) {
          setErrors(fieldErrors);
        } else {
          setSubmitError("Something went wrong. Please try again.");
        }
        return;
      }

      const data = (await response.json()) as SignupResponse;
      setAccountId(data.id);
      setForm(initialState);
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  if (accountId) {
    return (
      <div role="status">
        <p>Account created successfully! Your account id is {accountId}.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={form.name}
          onChange={(e) => updateField("name", e.target.value)}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <p id="name-error">{errors.name}</p>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={form.email}
          onChange={(e) => updateField("email", e.target.value)}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <p id="email-error">{errors.email}</p>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={form.password}
          onChange={(e) => updateField("password", e.target.value)}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <p id="password-error">{errors.password}</p>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm password</label>
        <input
          id="confirmPassword"
          type="password"
          value={form.confirmPassword}
          onChange={(e) => updateField("confirmPassword", e.target.value)}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && <p id="confirmPassword-error">{errors.confirmPassword}</p>}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={form.acceptTerms}
            onChange={(e) => updateField("acceptTerms", e.target.checked)}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <p id="acceptTerms-error">{errors.acceptTerms}</p>}
      </div>

      {submitError && <p role="alert">{submitError}</p>}

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useRef, useState, FormEvent } from "react";

interface FormState {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormState, string>>;

const initialState: FormState = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(form: FormState): FieldErrors {
  const errors: FieldErrors = {};

  if (!form.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!form.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(form.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!form.password) {
    errors.password = "Password is required.";
  } else if (form.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!form.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (form.confirmPassword !== form.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!form.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

interface SignupSuccessResponse {
  id: string;
}

interface SignupErrorResponse {
  errors: Partial<Record<keyof FormState, string>>;
}

const FORM_FIELDS: (keyof FormState)[] = [
  "name",
  "email",
  "password",
  "confirmPassword",
  "acceptTerms",
];

function isSignupErrorResponse(payload: unknown): payload is SignupErrorResponse {
  if (
    typeof payload !== "object" ||
    payload === null ||
    Array.isArray(payload) ||
    !("errors" in payload)
  ) {
    return false;
  }

  const { errors } = payload as { errors: unknown };
  if (typeof errors !== "object" || errors === null || Array.isArray(errors)) {
    return false;
  }

  return Object.entries(errors).every(
    ([key, value]) =>
      FORM_FIELDS.includes(key as keyof FormState) &&
      (value === undefined || typeof value === "string")
  );
}

function isSignupSuccessResponse(payload: unknown): payload is SignupSuccessResponse {
  return (
    typeof payload === "object" &&
    payload !== null &&
    "id" in payload &&
    typeof (payload as { id: unknown }).id === "string"
  );
}

export default function SignupForm() {
  const [form, setForm] = useState<FormState>(initialState);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);
  const latestRequestId = useRef(0);

  function updateField<K extends keyof FormState>(field: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting) {
      return;
    }

    setFormError(null);
    setAccountId(null);

    const clientErrors = validate(form);
    if (Object.keys(clientErrors).length > 0) {
      setErrors(clientErrors);
      return;
    }

    const requestId = ++latestRequestId.current;
    setSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: form.name,
          email: form.email,
          password: form.password,
          confirmPassword: form.confirmPassword,
          acceptTerms: form.acceptTerms,
        }),
      });

      const responseBody: unknown = await response.json().catch(() => null);
      if (requestId !== latestRequestId.current) {
        return;
      }

      if (!response.ok) {
        if (isSignupErrorResponse(responseBody)) {
          setErrors(responseBody.errors);
        } else {
          setFormError("Sign up failed. Please try again.");
        }
        return;
      }

      if (!isSignupSuccessResponse(responseBody)) {
        setFormError("Sign up failed. Please try again.");
        return;
      }

      setAccountId(responseBody.id);
      setForm(initialState);
      setErrors({});
      setFormError(null);
    } catch {
      if (requestId === latestRequestId.current) {
        setFormError("Sign up failed. Please check your connection and try again.");
      }
    } finally {
      if (requestId === latestRequestId.current) {
        setSubmitting(false);
      }
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <h1>Create an account</h1>

      {accountId && (
        <p role="status">Account created successfully! Your account id is {accountId}.</p>
      )}
      {formError && <p role="alert">{formError}</p>}

      <fieldset disabled={submitting}>
      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={form.name}
          onChange={(e) => updateField("name", e.target.value)}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <p id="name-error">{errors.name}</p>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={form.email}
          onChange={(e) => updateField("email", e.target.value)}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <p id="email-error">{errors.email}</p>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={form.password}
          onChange={(e) => updateField("password", e.target.value)}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <p id="password-error">{errors.password}</p>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm password</label>
        <input
          id="confirmPassword"
          type="password"
          value={form.confirmPassword}
          onChange={(e) => updateField("confirmPassword", e.target.value)}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && <p id="confirmPassword-error">{errors.confirmPassword}</p>}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={form.acceptTerms}
            onChange={(e) => updateField("acceptTerms", e.target.checked)}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <p id="acceptTerms-error">{errors.acceptTerms}</p>}
      </div>

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
      </fieldset>
    </form>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;
const TICK_INTERVAL_MS = 1_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    Number.isFinite(candidate.value) &&
    typeof candidate.unit === "string"
  );
}

function isMetricArray(data: unknown): data is Metric[] {
  return Array.isArray(data) && data.every(isMetric);
}

function dedupeByName(data: Metric[]): Metric[] {
  const seen = new Set<string>();
  const result: Metric[] = [];
  for (const metric of data) {
    if (seen.has(metric.name)) continue;
    seen.add(metric.name);
    result.push(metric);
  }
  return result;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState(() => Date.now());

  const previousValuesRef = useRef<Map<string, number>>(new Map());
  const inFlightRef = useRef<AbortController | null>(null);

  const fetchMetrics = useCallback(async () => {
    inFlightRef.current?.abort();
    const controller = new AbortController();
    inFlightRef.current = controller;

    try {
      const res = await fetch("/api/metrics", { signal: controller.signal });
      if (!res.ok) throw new Error(`Request failed: ${res.status}`);
      const data: unknown = await res.json();
      if (!isMetricArray(data)) throw new Error("Unexpected metrics response shape");

      // A newer request may have superseded this one after the fetch/JSON
      // steps already resolved; abort() alone won't stop that, so skip
      // applying state if we're no longer the current in-flight request.
      if (inFlightRef.current !== controller) return;

      const deduped = dedupeByName(data);
      const previousValues = previousValuesRef.current;
      const nextChanged = new Set<string>();
      for (const metric of deduped) {
        const prev = previousValues.get(metric.name);
        if (prev !== undefined && prev !== metric.value) {
          nextChanged.add(metric.name);
        }
      }

      previousValuesRef.current = new Map(deduped.map((m) => [m.name, m.value]));
      setMetrics(deduped);
      setChangedNames(nextChanged);
      setLastUpdated(new Date());
      setError(null);
    } catch (err) {
      if (err instanceof DOMException && err.name === "AbortError") return;
      if (inFlightRef.current !== controller) return;
      setError(err instanceof Error ? err.message : "Failed to load metrics");
    }
  }, []);

  useEffect(() => {
    let disposed = false;
    let timeoutId: ReturnType<typeof setTimeout> | null = null;

    // Schedules the next poll only once the current one has settled, so a
    // slow endpoint doesn't get its in-flight request aborted every
    // POLL_INTERVAL_MS by a fresh overlapping fetch.
    const poll = () => {
      timeoutId = null;
      fetchMetrics().finally(() => {
        if (disposed || document.hidden) return;
        timeoutId = setTimeout(poll, POLL_INTERVAL_MS);
      });
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        if (timeoutId !== null) {
          clearTimeout(timeoutId);
          timeoutId = null;
        }
      } else if (timeoutId === null) {
        poll();
      }
    };

    if (!document.hidden) poll();

    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      disposed = true;
      if (timeoutId !== null) clearTimeout(timeoutId);
      inFlightRef.current?.abort();
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [fetchMetrics]);

  useEffect(() => {
    if (!lastUpdated) return;
    const tickId = setInterval(() => setNow(Date.now()), TICK_INTERVAL_MS);
    return () => clearInterval(tickId);
  }, [lastUpdated]);

  const secondsAgo = lastUpdated ? Math.max(0, Math.floor((now - lastUpdated.getTime()) / 1000)) : null;

  return (
    <div className="metrics-panel">
      <header className="metrics-panel__header">
        <h2>Metrics</h2>
        {secondsAgo !== null && (
          <span className="metrics-panel__updated">
            Last updated {secondsAgo} second{secondsAgo === 1 ? "" : "s"} ago
          </span>
        )}
      </header>

      {error && <div className="metrics-panel__error">{error}</div>}

      <ul className="metrics-panel__list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={
              changedNames.has(metric.name)
                ? "metrics-panel__item metrics-panel__item--changed"
                : "metrics-panel__item"
            }
          >
            <span className="metrics-panel__name">{metric.name}</span>
            <span className="metrics-panel__value">
              {metric.value} {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, type FormEvent } from "react";

interface FormValues {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldErrors = Partial<Record<keyof FormValues, string>>;

interface SignupSuccessResponse {
  id: string;
}

interface SignupErrorResponse {
  errors?: Record<string, string>;
}

const INITIAL_VALUES: FormValues = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  if (!values.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!values.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(values.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!values.password) {
    errors.password = "Password is required.";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!values.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

const FORM_FIELD_KEYS: readonly (keyof FormValues)[] = [
  "name",
  "email",
  "password",
  "confirmPassword",
  "acceptTerms",
];

function isFieldErrorMap(candidate: unknown): candidate is Record<string, string> {
  if (typeof candidate !== "object" || candidate === null) {
    return false;
  }
  const entries = Object.entries(candidate as Record<string, unknown>);
  if (entries.length === 0) {
    return false;
  }
  if (!entries.every(([, message]) => typeof message === "string")) {
    return false;
  }
  return entries.some(
    ([key, message]) =>
      FORM_FIELD_KEYS.includes(key as keyof FormValues) && (message as string).length > 0,
  );
}

export default function SignupForm() {
  const [values, setValues] = useState<FormValues>(INITIAL_VALUES);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [formError, setFormError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [successId, setSuccessId] = useState<string | null>(null);

  function updateField<K extends keyof FormValues>(field: K, value: FormValues[K]) {
    setValues((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (submitting) {
      return;
    }

    const submittedValues: FormValues = {
      ...values,
      name: values.name.trim(),
      email: values.email.trim(),
    };

    const clientErrors = validate(submittedValues);
    if (Object.keys(clientErrors).length > 0) {
      setErrors(clientErrors);
      return;
    }

    setErrors({});
    setFormError(null);
    setSubmitting(true);

    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: submittedValues.name,
          email: submittedValues.email,
          password: submittedValues.password,
        }),
      });

      const responseBody: unknown = await response.json().catch(() => null);

      if (!response.ok) {
        const errorBody = responseBody as SignupErrorResponse | null;
        if (errorBody && isFieldErrorMap(errorBody.errors)) {
          setErrors(errorBody.errors as FieldErrors);
        } else {
          setFormError("Something went wrong. Please try again.");
        }
        return;
      }

      const successBody = responseBody as Partial<SignupSuccessResponse> | null;
      if (!successBody || typeof successBody.id !== "string") {
        setFormError("Unexpected response from server. Please try again.");
        return;
      }

      setSuccessId(successBody.id);
      setValues(INITIAL_VALUES);
    } catch {
      setFormError("Network error. Please check your connection and try again.");
    } finally {
      setSubmitting(false);
    }
  }

  if (successId) {
    return (
      <div role="status">
        <p>Account created successfully! Your account id is {successId}.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      {formError && <p role="alert">{formError}</p>}

      <fieldset disabled={submitting}>
        <div>
          <label htmlFor="signup-name">Name</label>
          <input
            id="signup-name"
            type="text"
            value={values.name}
            onChange={(e) => updateField("name", e.target.value)}
            aria-invalid={errors.name ? true : undefined}
            aria-describedby={errors.name ? "signup-name-error" : undefined}
          />
          {errors.name && <p id="signup-name-error">{errors.name}</p>}
        </div>

        <div>
          <label htmlFor="signup-email">Email</label>
          <input
            id="signup-email"
            type="email"
            value={values.email}
            onChange={(e) => updateField("email", e.target.value)}
            aria-invalid={errors.email ? true : undefined}
            aria-describedby={errors.email ? "signup-email-error" : undefined}
          />
          {errors.email && <p id="signup-email-error">{errors.email}</p>}
        </div>

        <div>
          <label htmlFor="signup-password">Password</label>
          <input
            id="signup-password"
            type="password"
            value={values.password}
            onChange={(e) => updateField("password", e.target.value)}
            aria-invalid={errors.password ? true : undefined}
            aria-describedby={errors.password ? "signup-password-error" : undefined}
          />
          {errors.password && <p id="signup-password-error">{errors.password}</p>}
        </div>

        <div>
          <label htmlFor="signup-confirm-password">Confirm Password</label>
          <input
            id="signup-confirm-password"
            type="password"
            value={values.confirmPassword}
            onChange={(e) => updateField("confirmPassword", e.target.value)}
            aria-invalid={errors.confirmPassword ? true : undefined}
            aria-describedby={
              errors.confirmPassword ? "signup-confirm-password-error" : undefined
            }
          />
          {errors.confirmPassword && (
            <p id="signup-confirm-password-error">{errors.confirmPassword}</p>
          )}
        </div>

        <div>
          <label htmlFor="signup-accept-terms">
            <input
              id="signup-accept-terms"
              type="checkbox"
              checked={values.acceptTerms}
              onChange={(e) => updateField("acceptTerms", e.target.checked)}
              aria-invalid={errors.acceptTerms ? true : undefined}
              aria-describedby={errors.acceptTerms ? "signup-accept-terms-error" : undefined}
            />
            I accept the terms and conditions
          </label>
          {errors.acceptTerms && <p id="signup-accept-terms-error">{errors.acceptTerms}</p>}
        </div>
      </fieldset>

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign Up"}
      </button>
    </form>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

interface ChatRoomProps {
  roomId: string;
}

const RECONNECT_DELAY_MS = 2000;
const MAX_MESSAGES = 200;

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.author === "string" &&
    typeof candidate.text === "string" &&
    typeof candidate.sentAt === "string"
  );
}

export default function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  // Reset messages synchronously during render when the room changes, so the
  // previous room's messages never flash on screen while the effect below
  // (which runs after paint) tears down the old socket and opens a new one.
  const [renderedRoomId, setRenderedRoomId] = useState(roomId);
  if (roomId !== renderedRoomId) {
    setRenderedRoomId(roomId);
    setMessages([]);
  }

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);
  const isUnmountedRef = useRef(false);

  useEffect(() => {
    isUnmountedRef.current = false;

    const connect = () => {
      if (isUnmountedRef.current) return;

      setIsReconnecting(false);

      const socket = new WebSocket(
        `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`,
      );
      socketRef.current = socket;

      socket.onopen = () => {
        setIsReconnecting(false);
      };

      socket.onmessage = (event) => {
        try {
          const parsed: unknown = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) => {
              const next = [...prev, parsed];
              return next.length > MAX_MESSAGES
                ? next.slice(next.length - MAX_MESSAGES)
                : next;
            });
          }
        } catch {
          // Ignore malformed messages.
        }
      };

      socket.onclose = () => {
        if (isUnmountedRef.current) return;
        setIsReconnecting(true);
        reconnectTimerRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      };

      socket.onerror = () => {
        socket.close();
      };
    };

    connect();

    return () => {
      isUnmountedRef.current = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      const socket = socketRef.current;
      if (socket) {
        socket.onopen = null;
        socket.onmessage = null;
        socket.onclose = null;
        socket.onerror = null;
        socket.close();
        socketRef.current = null;
      }
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(
      JSON.stringify({
        text,
        sentAt: new Date().toISOString(),
      }),
    );
    setDraft("");
  }, [draft]);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    sendMessage();
  };

  return (
    <div className="chat-room">
      {isReconnecting && (
        <div className="chat-room__banner" role="status">
          Reconnecting…
        </div>
      )}
      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>
      <form className="chat-room__composer" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit" disabled={draft.trim().length === 0}>
          Send
        </button>
      </form>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

interface ChatRoomProps {
  roomId: string;
}

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.author === "string" &&
    typeof v.text === "string" &&
    typeof v.sentAt === "string" &&
    !Number.isNaN(Date.parse(v.sentAt))
  );
}

const RECONNECT_DELAY_MS = 2000;

export function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isReconnecting, setIsReconnecting] = useState(false);
  const [draft, setDraft] = useState("");
  const [sendError, setSendError] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);

  const [prevRoomId, setPrevRoomId] = useState(roomId);
  if (roomId !== prevRoomId) {
    setPrevRoomId(roomId);
    setMessages([]);
    setIsReconnecting(false);
    setSendError(false);
  }

  useEffect(() => {
    let cancelled = false;

    const connect = () => {
      if (cancelled) return;

      const socket = new WebSocket(
        `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`
      );
      socketRef.current = socket;

      socket.onopen = () => {
        if (cancelled) return;
        setIsReconnecting(false);
      };

      socket.onmessage = (event) => {
        if (cancelled) return;
        try {
          const parsed: unknown = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed]);
          }
        } catch (error) {
          console.error("Failed to parse chat message", error);
        }
      };

      socket.onclose = () => {
        if (cancelled) return;
        setIsReconnecting(true);
        reconnectTimerRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      };

      socket.onerror = () => {
        socket.close();
      };
    };

    connect();

    return () => {
      cancelled = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      const socket = socketRef.current;
      if (socket) {
        socket.onopen = null;
        socket.onmessage = null;
        socket.onclose = null;
        socket.onerror = null;
        socket.close();
        socketRef.current = null;
      }
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    if (text === "") return;

    const socket = socketRef.current;
    if (!socket || socket.readyState !== WebSocket.OPEN) {
      setSendError(true);
      return;
    }

    try {
      socket.send(
        JSON.stringify({
          author: "me",
          text,
        })
      );
      setDraft("");
      setSendError(false);
    } catch (error) {
      console.error("Failed to send chat message", error);
      setSendError(true);
    }
  }, [draft]);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    sendMessage();
  };

  return (
    <div className="chat-room">
      {isReconnecting && (
        <div className="chat-room__banner" role="status">
          Reconnecting…
        </div>
      )}

      {sendError && (
        <div className="chat-room__banner chat-room__banner--error" role="alert">
          Message failed to send. Please try again.
        </div>
      )}

      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form className="chat-room__composer" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

