import { useEffect, useRef, useState, type FormEvent } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.author === "string" &&
    typeof v.text === "string" &&
    typeof v.sentAt === "string" &&
    !Number.isNaN(Date.parse(v.sentAt))
  );
}

const RECONNECT_DELAY_MS = 2000;

export interface ChatRoomProps {
  roomId: string;
}

export function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    setMessages([]);
    setIsReconnecting(false);

    let cancelled = false;
    let reconnectTimer: ReturnType<typeof setTimeout> | undefined;
    let socket: WebSocket | undefined;

    const connect = () => {
      if (cancelled) return;

      const ws = new WebSocket(
        `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`,
      );
      socket = ws;
      socketRef.current = ws;

      ws.addEventListener("open", () => {
        if (cancelled) return;
        setIsReconnecting(false);
      });

      ws.addEventListener("message", (event: MessageEvent) => {
        if (cancelled) return;
        try {
          const parsed: unknown = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed]);
          }
        } catch (error) {
          console.error("Failed to parse chat message", error);
        }
      });

      ws.addEventListener("close", () => {
        if (cancelled) return;
        setIsReconnecting(true);
        reconnectTimer = setTimeout(connect, RECONNECT_DELAY_MS);
      });

      ws.addEventListener("error", () => {
        ws.close();
      });
    };

    connect();

    return () => {
      cancelled = true;
      if (reconnectTimer !== undefined) clearTimeout(reconnectTimer);
      socketRef.current = null;
      socket?.close();
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(JSON.stringify({ text }));
    setDraft("");
  };

  return (
    <div className="chat-room">
      {isReconnecting && (
        <div className="chat-room__banner" role="status">
          Reconnecting…
        </div>
      )}

      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form className="chat-room__composer" onSubmit={handleSubmit}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

export default ChatRoom;

import { useEffect, useState, type FormEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function isTodo(value: unknown): value is Todo {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as Todo).id === "string" &&
    typeof (value as Todo).text === "string" &&
    typeof (value as Todo).done === "boolean"
  );
}

function loadTodos(): Todo[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    const seenIds = new Set<string>();
    const todos: Todo[] = [];
    for (const item of parsed) {
      if (isTodo(item) && !seenIds.has(item.id)) {
        seenIds.add(item.id);
        todos.push(item);
      }
    }
    return todos;
  } catch {
    return [];
  }
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(loadTodos);
  const [filter, setFilter] = useState<Filter>("all");
  const [newText, setNewText] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch {
      // storage unavailable or full; persistence is best-effort
    }
  }, [todos]);

  function addTodo(e: FormEvent) {
    e.preventDefault();
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [
      ...prev,
      { id: crypto.randomUUID(), text, done: false },
    ]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((t) => (t.id === id ? { ...t, done: !t.done } : t))
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((t) => t.id !== id));
  }

  function startEditing(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function commitEdit(id: string) {
    const text = editingText.trim();
    setTodos((prev) =>
      prev.map((t) => (t.id === id ? { ...t, text: text || t.text } : t))
    );
    setEditingId(null);
    setEditingText("");
  }

  function cancelEdit() {
    setEditingId(null);
    setEditingText("");
  }

  function moveWithinFilter(id: string, direction: "up" | "down") {
    setTodos((prev) => {
      const visible = prev.filter((t) => {
        if (filter === "active") return !t.done;
        if (filter === "done") return t.done;
        return true;
      });
      const visibleIndex = visible.findIndex((t) => t.id === id);
      if (visibleIndex === -1) return prev;
      const neighbor =
        direction === "up"
          ? visible[visibleIndex - 1]
          : visible[visibleIndex + 1];
      if (!neighbor) return prev;
      const next = [...prev];
      const i = next.findIndex((t) => t.id === id);
      const j = next.findIndex((t) => t.id === neighbor.id);
      [next[i], next[j]] = [next[j], next[i]];
      return next;
    });
  }

  const filteredTodos = todos.filter((t) => {
    if (filter === "active") return !t.done;
    if (filter === "done") return t.done;
    return true;
  });

  const remainingCount = todos.filter((t) => !t.done).length;

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form onSubmit={addTodo}>
        <input
          type="text"
          value={newText}
          onChange={(e) => setNewText(e.target.value)}
          placeholder="Add a todo..."
          aria-label="New todo text"
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-filters" role="group" aria-label="Filter todos">
        {(["all", "active", "done"] as const).map((f) => (
          <button
            key={f}
            type="button"
            onClick={() => setFilter(f)}
            aria-pressed={filter === f}
            disabled={filter === f}
          >
            {f[0].toUpperCase() + f.slice(1)}
          </button>
        ))}
      </div>

      <ul className="todo-list">
        {filteredTodos.map((todo, visibleIndex) => {
          const isEditing = editingId === todo.id;
          return (
            <li key={todo.id} className="todo-item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
                aria-label={`Mark "${todo.text}" as ${
                  todo.done ? "active" : "done"
                }`}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(e) => setEditingText(e.target.value)}
                  onBlur={() => commitEdit(todo.id)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") commitEdit(todo.id);
                    if (e.key === "Escape") cancelEdit();
                  }}
                  aria-label="Edit todo text"
                />
              ) : (
                <span
                  className="todo-text"
                  style={{
                    textDecoration: todo.done ? "line-through" : "none",
                  }}
                  onDoubleClick={() => startEditing(todo)}
                >
                  {todo.text}
                </span>
              )}

              <button
                type="button"
                onClick={() => startEditing(todo)}
                aria-label={`Edit "${todo.text}"`}
              >
                Edit
              </button>
              <button
                type="button"
                onClick={() => moveWithinFilter(todo.id, "up")}
                disabled={visibleIndex === 0}
                aria-label={`Move "${todo.text}" up`}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveWithinFilter(todo.id, "down")}
                disabled={visibleIndex === filteredTodos.length - 1}
                aria-label={`Move "${todo.text}" down`}
              >
                ↓
              </button>
              <button
                type="button"
                onClick={() => deleteTodo(todo.id)}
                aria-label={`Delete "${todo.text}"`}
              >
                Delete
              </button>
            </li>
          );
        })}
      </ul>

      <p className="todo-count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";

interface TodoItem {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function isTodoItem(value: unknown): value is TodoItem {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as TodoItem).id === "string" &&
    typeof (value as TodoItem).text === "string" &&
    typeof (value as TodoItem).done === "boolean"
  );
}

function loadItems(): TodoItem[] {
  if (typeof window === "undefined" || !window.localStorage) return [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isTodoItem);
  } catch {
    return [];
  }
}

export default function TodoBoard() {
  const [items, setItems] = useState<TodoItem[]>([]);
  const [filter, setFilter] = useState<Filter>("all");
  const [newText, setNewText] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");
  const isCancellingEditRef = useRef(false);
  const hasLoadedRef = useRef(false);

  useEffect(() => {
    setItems(loadItems());
    hasLoadedRef.current = true;
  }, []);

  useEffect(() => {
    if (!hasLoadedRef.current) return;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    } catch {
      // Storage may be full or unavailable (e.g. private browsing); skip persisting.
    }
  }, [items]);

  const remainingCount = useMemo(
    () => items.filter((item) => !item.done).length,
    [items],
  );

  const visibleItems = useMemo(() => {
    switch (filter) {
      case "active":
        return items.filter((item) => !item.done);
      case "done":
        return items.filter((item) => item.done);
      default:
        return items;
    }
  }, [items, filter]);

  function addItem() {
    const text = newText.trim();
    if (!text) return;
    setItems((prev) => [
      ...prev,
      { id: crypto.randomUUID(), text, done: false },
    ]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setItems((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, done: !item.done } : item,
      ),
    );
  }

  function deleteItem(id: string) {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(item: TodoItem) {
    setEditingId(item.id);
    setEditingText(item.text);
  }

  function commitEdit() {
    if (isCancellingEditRef.current) {
      isCancellingEditRef.current = false;
      return;
    }
    if (editingId === null) return;
    const text = editingText.trim();
    setItems((prev) =>
      prev.map((item) =>
        item.id === editingId
          ? { ...item, text: text || item.text }
          : item,
      ),
    );
    setEditingId(null);
    setEditingText("");
  }

  function cancelEdit() {
    isCancellingEditRef.current = true;
    setEditingId(null);
    setEditingText("");
  }

  function moveItem(id: string, direction: -1 | 1) {
    setItems((prev) => {
      const index = prev.findIndex((item) => item.id === id);
      const targetIndex = index + direction;
      if (index === -1 || targetIndex < 0 || targetIndex >= prev.length) {
        return prev;
      }
      const next = [...prev];
      [next[index], next[targetIndex]] = [next[targetIndex], next[index]];
      return next;
    });
  }

  return (
    <div>
      <h1>Todo Board</h1>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          addItem();
        }}
      >
        <input
          type="text"
          value={newText}
          onChange={(e) => setNewText(e.target.value)}
          placeholder="Add a new item"
        />
        <button type="submit">Add</button>
      </form>

      <div role="group" aria-label="Filter items">
        {(["all", "active", "done"] as const).map((f) => (
          <button
            key={f}
            type="button"
            aria-pressed={filter === f}
            onClick={() => setFilter(f)}
            disabled={filter === f}
          >
            {f}
          </button>
        ))}
      </div>

      <p>{remainingCount} item(s) remaining</p>

      <ul>
        {visibleItems.map((item) => {
          const index = items.findIndex((i) => i.id === item.id);
          const isEditing = editingId === item.id;
          return (
            <li key={item.id}>
              <input
                type="checkbox"
                checked={item.done}
                onChange={() => toggleDone(item.id)}
                aria-label={`Mark "${item.text}" as ${item.done ? "active" : "done"}`}
              />

              {isEditing ? (
                <form
                  style={{ display: "inline" }}
                  onSubmit={(e) => {
                    e.preventDefault();
                    commitEdit();
                  }}
                >
                  <input
                    type="text"
                    value={editingText}
                    autoFocus
                    onChange={(e) => setEditingText(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Escape") cancelEdit();
                    }}
                    onBlur={commitEdit}
                  />
                </form>
              ) : (
                <span
                  onDoubleClick={() => startEditing(item)}
                  style={{ textDecoration: item.done ? "line-through" : "none" }}
                >
                  {item.text}
                </span>
              )}

              <button type="button" onClick={() => startEditing(item)}>
                Edit
              </button>
              <button
                type="button"
                onClick={() => moveItem(item.id, -1)}
                disabled={index <= 0}
              >
                Move up
              </button>
              <button
                type="button"
                onClick={() => moveItem(item.id, 1)}
                disabled={index === -1 || index >= items.length - 1}
              >
                Move down
              </button>
              <button type="button" onClick={() => deleteItem(item.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function isTodo(value: unknown): value is Todo {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as Todo).id === "string" &&
    typeof (value as Todo).text === "string" &&
    typeof (value as Todo).done === "boolean"
  );
}

function loadTodos(): Todo[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isTodo);
  } catch {
    return [];
  }
}

function generateId(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(loadTodos);
  const [filter, setFilter] = useState<Filter>("all");
  const [newText, setNewText] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");
  const skipBlurCommit = useRef(false);

  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch {
      // storage unavailable or quota exceeded; edits remain in memory only
    }
  }, [todos]);

  const remainingCount = useMemo(
    () => todos.filter((todo) => !todo.done).length,
    [todos]
  );

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function addTodo() {
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [
      ...prev,
      { id: generateId(), text, done: false },
    ]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo
      )
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
  }

  function startEditing(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function commitEdit() {
    const text = editingText.trim();
    if (editingId === null) return;
    if (!text) {
      deleteTodo(editingId);
    } else {
      setTodos((prev) =>
        prev.map((todo) =>
          todo.id === editingId ? { ...todo, text } : todo
        )
      );
    }
    setEditingId(null);
    setEditingText("");
  }

  function cancelEdit() {
    skipBlurCommit.current = true;
    setEditingId(null);
    setEditingText("");
  }

  function swapTodos(idA: string, idB: string) {
    setTodos((prev) => {
      const indexA = prev.findIndex((todo) => todo.id === idA);
      const indexB = prev.findIndex((todo) => todo.id === idB);
      if (indexA === -1 || indexB === -1) return prev;
      const next = [...prev];
      [next[indexA], next[indexB]] = [next[indexB], next[indexA]];
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form
        onSubmit={(event) => {
          event.preventDefault();
          addTodo();
        }}
      >
        <input
          type="text"
          value={newText}
          onChange={(event) => setNewText(event.target.value)}
          placeholder="Add a new task..."
          aria-label="New task"
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-board__filters">
        {(["all", "active", "done"] as const).map((value) => (
          <button
            key={value}
            type="button"
            onClick={() => setFilter(value)}
            aria-pressed={filter === value}
            disabled={filter === value}
          >
            {value[0].toUpperCase() + value.slice(1)}
          </button>
        ))}
      </div>

      <p>{remainingCount} item(s) remaining</p>

      <ul className="todo-board__list">
        {visibleTodos.map((todo, visibleIndex) => {
          const isEditing = editingId === todo.id;
          const disableOtherActions = editingId !== null && !isEditing;
          const upNeighbor = visibleTodos[visibleIndex - 1];
          const downNeighbor = visibleTodos[visibleIndex + 1];
          return (
            <li key={todo.id} className="todo-board__item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
                aria-label={`Mark "${todo.text}" as done`}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  autoFocus
                  onChange={(event) => setEditingText(event.target.value)}
                  onBlur={() => {
                    if (skipBlurCommit.current) {
                      skipBlurCommit.current = false;
                      return;
                    }
                    commitEdit();
                  }}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") commitEdit();
                    if (event.key === "Escape") cancelEdit();
                  }}
                  aria-label="Edit task"
                />
              ) : (
                <span
                  onDoubleClick={() => startEditing(todo)}
                  style={{
                    textDecoration: todo.done ? "line-through" : "none",
                  }}
                >
                  {todo.text}
                </span>
              )}

              <button
                type="button"
                onClick={() => startEditing(todo)}
                disabled={disableOtherActions}
              >
                Edit
              </button>
              <button
                type="button"
                onClick={() => upNeighbor && swapTodos(todo.id, upNeighbor.id)}
                disabled={disableOtherActions || !upNeighbor}
              >
                Up
              </button>
              <button
                type="button"
                onClick={() =>
                  downNeighbor && swapTodos(todo.id, downNeighbor.id)
                }
                disabled={disableOtherActions || !downNeighbor}
              >
                Down
              </button>
              <button
                type="button"
                onClick={() => deleteTodo(todo.id)}
                disabled={disableOtherActions}
              >
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  error: Error | null;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

export function useUserProfiles(userIds: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [loading, setLoading] = useState(userIds.length > 0);
  const [error, setError] = useState<Error | null>(null);

  const idsKey = JSON.stringify(userIds);

  useEffect(() => {
    const ids: string[] = JSON.parse(idsKey);

    if (ids.length === 0) {
      setProfiles({});
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    Promise.all(
      ids.map(async (id) => {
        const response = await fetch(`/api/users/${encodeURIComponent(id)}`);
        if (!response.ok) {
          throw new Error(`Failed to load user ${id}: ${response.status}`);
        }
        const userPayload: unknown = await response.json();
        if (!isUser(userPayload) || userPayload.id !== id) {
          throw new Error(`Malformed user data for ${id}`);
        }
        return userPayload;
      }),
    )
      .then((users) => {
        if (cancelled) return;
        const byId: Record<string, User> = Object.create(null);
        for (const user of users) {
          byId[user.id] = user;
        }
        setProfiles(byId);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err : new Error("Failed to load user profiles"));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [idsKey]);

  return { profiles, loading, error };
}

import { useEffect, useState } from "react";

export interface User {
