import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Map<string, User>;
  loading: boolean;
  errors: Map<string, string>;
}

function isUser(value: unknown): value is User {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as Record<string, unknown>).id === "string" &&
    typeof (value as Record<string, unknown>).displayName === "string" &&
    typeof (value as Record<string, unknown>).bio === "string" &&
    typeof (value as Record<string, unknown>).avatarUrl === "string"
  );
}

export function useUserProfiles(userIds: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Map<string, User>>(new Map());
  const [errors, setErrors] = useState<Map<string, string>>(new Map());
  const [loading, setLoading] = useState(userIds.length > 0);

  useEffect(() => {
    if (userIds.length === 0) {
      setProfiles(new Map());
      setErrors(new Map());
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setProfiles(new Map());
    setErrors(new Map());

    Promise.all(
      userIds.map(async (id) => {
        try {
          const response = await fetch(`/api/users/${encodeURIComponent(id)}`);
          if (!response.ok) {
            throw new Error(`Failed to load user ${id}: ${response.status}`);
          }
          const body = await response.json();
          if (!isUser(body)) {
            throw new Error(`Received malformed profile data for user ${id}`);
          }
          return { id, user: body, error: null as string | null };
        } catch (err) {
          const message = err instanceof Error ? err.message : `Failed to load user ${id}`;
          return { id, user: null as User | null, error: message };
        }
      })
    ).then((results) => {
      if (cancelled) return;

      const nextProfiles = new Map<string, User>();
      const nextErrors = new Map<string, string>();
      for (const result of results) {
        if (result.user) {
          nextProfiles.set(result.id, result.user);
        } else if (result.error) {
          nextErrors.set(result.id, result.error);
        }
      }

      setProfiles(nextProfiles);
      setErrors(nextErrors);
      setLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [JSON.stringify(userIds)]);

  return { profiles, loading, errors };
}

