struct SearchResult: Identifiable, Decodable {
    let id: String
    let title: String
    let subtitle: String
}

private struct SearchResponse: Decodable {
    let results: [SearchResult]
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = ""
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private var searchTask: Task<Void, Never>?
    private let debounceNanoseconds: UInt64
    private let session: URLSession

    init(debounceInterval: TimeInterval = 0.3, session: URLSession = .shared) {
        let safeInterval = debounceInterval.isFinite ? max(0, debounceInterval) : 0
        let nanoseconds = safeInterval * 1_000_000_000
        self.debounceNanoseconds = nanoseconds < TimeInterval(UInt64.max)
            ? UInt64(nanoseconds)
            : UInt64.max
        self.session = session
    }

    func queryChanged() {
        searchTask?.cancel()

        let trimmedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedQuery.isEmpty else {
            results = []
            errorMessage = nil
            isLoading = false
            return
        }

        searchTask = Task { [debounceNanoseconds, weak self] in
            do {
                try await Task.sleep(nanoseconds: debounceNanoseconds)
            } catch {
                return
            }
            guard !Task.isCancelled else { return }
            await self?.performSearch(for: trimmedQuery)
        }
    }

    private func performSearch(for query: String) async {
        isLoading = true
        errorMessage = nil

        var components = URLComponents(string: "https://api.example.com/search")
        components?.queryItems = [URLQueryItem(name: "q", value: query)]

        guard let url = components?.url else {
            isLoading = false
            errorMessage = "Invalid search URL."
            return
        }

        do {
            let (data, response) = try await session.data(from: url)
            guard !Task.isCancelled else { return }

            guard let httpResponse = response as? HTTPURLResponse,
                  (200..<300).contains(httpResponse.statusCode) else {
                isLoading = false
                errorMessage = "Search request failed."
                return
            }

            let decoded = try JSONDecoder().decode(SearchResponse.self, from: data)
            guard !Task.isCancelled else { return }

            results = decoded.results
            isLoading = false
        } catch is CancellationError {
            // Superseded by a newer search; leave state untouched.
        } catch {
            guard !Task.isCancelled else { return }
            isLoading = false
            errorMessage = "Something went wrong: \(error.localizedDescription)"
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 0) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .padding()
                .onChange(of: viewModel.query) { _ in
                    viewModel.queryChanged()
                }

            Divider()

            content
        }
        .frame(minWidth: 320, minHeight: 400)
    }

    @ViewBuilder
    private var content: some View {
        if viewModel.isLoading {
            Spacer()
            ProgressView("Searching…")
            Spacer()
        } else if let errorMessage = viewModel.errorMessage {
            Spacer()
            Text(errorMessage)
                .foregroundColor(.red)
                .multilineTextAlignment(.center)
                .padding()
            Spacer()
        } else if viewModel.results.isEmpty {
            Spacer()
            Text(viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                 ? "Start typing to search."
                 : "No results found.")
                .foregroundColor(.secondary)
            Spacer()
        } else {
            List(viewModel.results) { result in
                VStack(alignment: .leading, spacing: 2) {
                    Text(result.title)
                        .font(.headline)
                    Text(result.subtitle)
                        .font(.subheadline)
                        .foregroundColor(.secondary)
                }
            }
        }
    }
}

import { useEffect, useState } from "react";
import type { UserProfile } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, UserProfile>;
  errors: Record<string, string>;
  loading: boolean;
}

function isUserProfile(value: unknown): value is UserProfile {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, UserProfile>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(ids.length > 0);

  const idsKey = JSON.stringify(ids);

  useEffect(() => {
    const currentIds: string[] = JSON.parse(idsKey);
    if (currentIds.length === 0) {
      setProfiles({});
      setErrors({});
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setProfiles({});
    setErrors({});

    Promise.all(
      currentIds.map(async (id) => {
        try {
          const response = await fetch(
            `/api/users/${encodeURIComponent(id)}`,
            {
              signal: controller.signal,
            }
          );
          if (!response.ok) {
            throw new Error(`Failed to load user ${id}: ${response.status}`);
          }
          const rawProfile: unknown = await response.json();
          if (!isUserProfile(rawProfile)) {
            throw new Error(`Malformed profile data for user ${id}`);
          }
          if (rawProfile.id !== id) {
            throw new Error(`Received profile for wrong user: expected ${id}, got ${rawProfile.id}`);
          }
          setProfiles((prev) => ({ ...prev, [id]: rawProfile }));
        } catch (err) {
          if (controller.signal.aborted) return;
          const message =
            err instanceof Error ? err.message : `Failed to load user ${id}`;
          setErrors((prev) => ({ ...prev, [id]: message }));
        }
      })
    ).then(() => {
      if (!controller.signal.aborted) {
        setLoading(false);
      }
    });

    return () => controller.abort();
  }, [idsKey]);

  return { profiles, errors, loading };
}

