        timer?.invalidate()
    }

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startTime = Self.now()
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            self?.tick()
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        if let startTime {
            accumulated += Self.now() - startTime
        }
        startTime = nil
        elapsed = accumulated
    }

    func reset() {
        stop()
        elapsed = 0
        accumulated = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        laps.append(elapsed)
    }

    private func tick() {
        guard let startTime else { return }
        elapsed = accumulated + Self.now() - startTime
    }

    // Monotonic clock: immune to wall-clock adjustments, unlike Date().
    private static func now() -> TimeInterval {
        ProcessInfo.processInfo.systemUptime
    }

    static func formatted(_ time: TimeInterval) -> String {
        let totalHundredths = Int((time * 100).rounded())
        let minutes = totalHundredths / 6000
        let seconds = (totalHundredths / 100) % 60
        let hundredths = totalHundredths % 100
        return String(format: "%02d:%02d.%02d", minutes, seconds, hundredths)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(StopwatchViewModel.formatted(viewModel.elapsed))
                .font(.system(size: 48, weight: .medium, design: .monospaced))
