@MainActor
final class SettingsStore: ObservableObject {
    static let refreshIntervalOptions: [TimeInterval] = [15, 30, 60, 300, 900]
    static let defaultRefreshInterval: TimeInterval = 60

    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    @Published var displayName: String {
        didSet { persist { $0.set(displayName, forKey: Keys.displayName) } }
    }

    @Published var theme: AppTheme {
        didSet { persist { $0.set(theme.rawValue, forKey: Keys.theme) } }
    }

    @Published var notificationsEnabled: Bool {
        didSet { persist { $0.set(notificationsEnabled, forKey: Keys.notificationsEnabled) } }
    }

    @Published var refreshInterval: TimeInterval {
        didSet { persist { $0.set(refreshInterval, forKey: Keys.refreshInterval) } }
    }

    private let defaults: UserDefaults
    private var isApplyingExternalChange = false
    private var notificationObserver: NSObjectProtocol?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.displayName = defaults.string(forKey: Keys.displayName) ?? ""
        self.theme = AppTheme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        self.notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        self.refreshInterval = Self.sanitizedRefreshInterval(
            defaults.object(forKey: Keys.refreshInterval) as? TimeInterval
        )

        notificationObserver = NotificationCenter.default.addObserver(
            forName: UserDefaults.didChangeNotification,
            object: defaults,
            queue: .main
        ) { [weak self] _ in
            MainActor.assumeIsolated { self?.reloadFromDefaults() }
        }
    }

    deinit {
        if let notificationObserver {
            NotificationCenter.default.removeObserver(notificationObserver)
        }
    }

    /// Writes a changed value unless the change originated from `reloadFromDefaults`,
    /// which would otherwise re-post `didChangeNotification` and recurse.
    private func persist(_ write: (UserDefaults) -> Void) {
        guard !isApplyingExternalChange else { return }
        write(defaults)
    }

    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        if newDisplayName != displayName { displayName = newDisplayName }

        let newTheme = AppTheme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        if newTheme != theme { theme = newTheme }

        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        if newNotificationsEnabled != notificationsEnabled { notificationsEnabled = newNotificationsEnabled }

        let newRefreshInterval = Self.sanitizedRefreshInterval(
            defaults.object(forKey: Keys.refreshInterval) as? TimeInterval
        )
        if newRefreshInterval != refreshInterval { refreshInterval = newRefreshInterval }
    }

    /// Falls back to the closest allowed option so a stored or externally written
    /// value never leaves the picker without a matching selection.
    private static func sanitizedRefreshInterval(_ stored: TimeInterval?) -> TimeInterval {
        guard let stored else { return defaultRefreshInterval }
        if refreshIntervalOptions.contains(stored) { return stored }
        return refreshIntervalOptions.min(by: { abs($0 - stored) < abs($1 - stored) }) ?? defaultRefreshInterval
    }
}

