import SwiftUI

#if canImport(UIKit)
import UIKit
public typealias PlatformImage = UIImage
#elseif canImport(AppKit)
import AppKit
public typealias PlatformImage = NSImage
#endif

extension Image {
    init(platformImage: PlatformImage) {
        #if canImport(UIKit)
        self.init(uiImage: platformImage)
        #elseif canImport(AppKit)
        self.init(nsImage: platformImage)
        #endif
    }
}

/// A thumbnail plus the moment it was fetched, kept together so the
/// displayed "downloaded" date doesn't change when the cache is re-read.
///
/// `@unchecked Sendable`: `PlatformImage` (UIImage/NSImage) predates Swift
/// concurrency and isn't marked `Sendable`, but instances here are never
/// mutated after creation, so sharing them across isolation domains is safe.
struct CachedThumbnail: @unchecked Sendable {
    let image: PlatformImage
    let downloadDate: Date
}

enum ThumbnailLoadError: Error {
    case invalidImageData
}

/// Shared in-memory cache so scrolling a thumbnail back into view reuses
/// the already-downloaded image instead of re-fetching it. Bounded to
/// `capacity` entries (evicting least-recently-used) so browsing many
/// distinct URLs doesn't grow memory without limit, and de-duplicates
/// concurrent misses for the same URL into a single download.
actor ThumbnailCache {
    static let shared = ThumbnailCache()

    private let capacity = 100
    private var storage: [URL: CachedThumbnail] = [:]
    private var accessOrder: [URL] = []
    private var inFlightTasks: [URL: Task<CachedThumbnail, Error>] = [:]

    func thumbnail(for url: URL) async throws -> CachedThumbnail {
        if let cached = storage[url] {
            touch(url)
            return cached
        }

        if let existing = inFlightTasks[url] {
            return try await existing.value
        }

        let task = Task<CachedThumbnail, Error> {
            let (data, _) = try await URLSession.shared.data(from: url)
            guard let image = PlatformImage(data: data) else {
                throw ThumbnailLoadError.invalidImageData
            }
            return CachedThumbnail(image: image, downloadDate: Date())
        }
        inFlightTasks[url] = task

        do {
            let entry = try await task.value
            store(entry, for: url)
            inFlightTasks[url] = nil
            return entry
        } catch {
            inFlightTasks[url] = nil
            throw error
        }
    }

    private func store(_ entry: CachedThumbnail, for url: URL) {
        storage[url] = entry
        touch(url)
        if accessOrder.count > capacity, let oldest = accessOrder.first {
            accessOrder.removeFirst()
            storage[oldest] = nil
        }
    }

    private func touch(_ url: URL) {
        accessOrder.removeAll { $0 == url }
        accessOrder.append(url)
    }
}

func loadThumbnail(from url: URL) async throws -> CachedThumbnail {
    try await ThumbnailCache.shared.thumbnail(for: url)
}

struct ThumbnailCell: View {
    let url: URL

    @State private var thumbnail: CachedThumbnail?
    @State private var failed = false

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color.secondary.opacity(0.15))

                if let thumbnail {
                    Image(platformImage: thumbnail.image)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                        .clipShape(RoundedRectangle(cornerRadius: 8))
