import Foundation
import SwiftUI

struct Lap: Identifiable {
    let id = UUID()
    let number: Int
    let splitTime: TimeInterval
    let totalTime: TimeInterval
}

@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsedTime: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startInstant: ContinuousClock.Instant?
    private var accumulatedTime: TimeInterval = 0
    private var lastLapTotal: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startInstant = ContinuousClock.now
        let timer = Timer(timeInterval: 0.01, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.tick()
            }
        }
        // .common keeps the display updating while the run loop is in tracking
        // mode (e.g. during scroll interactions).
        RunLoop.current.add(timer, forMode: .common)
        self.timer = timer
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        accumulatedTime = currentElapsedTime()
        elapsedTime = accumulatedTime
        startInstant = nil
    }

    func reset() {
        stop()
        elapsedTime = 0
        accumulatedTime = 0
        lastLapTotal = 0
        laps.removeAll()
    }

    func lap() {
        let current = currentElapsedTime()
        elapsedTime = current
        let split = current - lastLapTotal
        lastLapTotal = current
        laps.insert(Lap(number: laps.count + 1, splitTime: split, totalTime: current), at: 0)
    }

    private func tick() {
        elapsedTime = currentElapsedTime()
    }

    // Computed fresh (rather than reading the timer-updated @Published value)
    // so stop()/lap() never report a stale reading from between ticks.
    private func currentElapsedTime() -> TimeInterval {
        guard let startInstant else { return accumulatedTime }
        return accumulatedTime + (ContinuousClock.now - startInstant).timeIntervalValue
    }

    deinit {
        timer?.invalidate()
    }
}

private extension Duration {
    var timeIntervalValue: TimeInterval {
        let components = components
        return TimeInterval(components.seconds) + TimeInterval(components.attoseconds) / 1e18
    }
}

func formattedElapsedTime(_ time: TimeInterval) -> String {
    let minutes = Int(time) / 60
    let seconds = Int(time) % 60
    let centiseconds = Int((time.truncatingRemainder(dividingBy: 1)) * 100)
    return String(format: "%02d:%02d.%02d", minutes, seconds, centiseconds)
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(formattedElapsedTime(viewModel.elapsedTime))
                .font(.system(size: 56, weight: .medium, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    viewModel.isRunning ? viewModel.stop() : viewModel.start()
                }
                .keyboardShortcut(.defaultAction)

                Button("Lap") {
                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)

                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(viewModel.isRunning && viewModel.elapsedTime == 0)
            }
            .buttonStyle(.bordered)

            List(viewModel.laps) { lap in
                HStack {
                    Text("Lap \(lap.number)")
                        .foregroundStyle(.secondary)
                    Spacer()
                    Text(formattedElapsedTime(lap.splitTime))
                        .monospacedDigit()
                    Spacer()
                    Text(formattedElapsedTime(lap.totalTime))
                        .monospacedDigit()
                        .foregroundStyle(.secondary)
                }
            }
        }
        .padding()
        .frame(minWidth: 320, minHeight: 400)
    }
}

