enum ThumbnailError: Error {
    case invalidImageData
    case badResponse(statusCode: Int)
}

struct CachedThumbnail {
    let image: PlatformImage
    let downloadDate: Date
}

/// Shared in-memory cache so scrolling back through the grid reuses
/// already-downloaded thumbnails instead of re-fetching them.
actor ThumbnailCache {
    static let shared = ThumbnailCache()

    /// Upper bound on retained thumbnails; oldest-accessed entries are evicted
    /// once this is exceeded, so an unbounded or changing URL set can't grow
    /// memory forever.
    private let maxCachedThumbnails = 200

    private var thumbnails: [URL: CachedThumbnail] = [:]
    private var accessOrder: [URL] = []
    private var inFlightTasks: [URL: Task<CachedThumbnail, Error>] = [:]

    func thumbnail(for url: URL) async throws -> CachedThumbnail {
        if let cached = thumbnails[url] {
            recordAccess(url)
            return cached
        }
        if let existing = inFlightTasks[url] {
            return try await existing.value
        }

        let task = Task<CachedThumbnail, Error> {
            let (data, response) = try await URLSession.shared.data(from: url)
            if let httpResponse = response as? HTTPURLResponse,
               !(200...299).contains(httpResponse.statusCode) {
                throw ThumbnailError.badResponse(statusCode: httpResponse.statusCode)
            }
            guard let image = PlatformImage(data: data) else {
                throw ThumbnailError.invalidImageData
            }
            return CachedThumbnail(image: image, downloadDate: Date())
        }
        inFlightTasks[url] = task

        do {
            let result = try await task.value
            thumbnails[url] = result
            recordAccess(url)
            inFlightTasks[url] = nil
            return result
        } catch {
            inFlightTasks[url] = nil
            throw error
        }
    }

    private func recordAccess(_ url: URL) {
        if let index = accessOrder.firstIndex(of: url) {
            accessOrder.remove(at: index)
        }
        accessOrder.append(url)
        if accessOrder.count > maxCachedThumbnails {
            let oldest = accessOrder.removeFirst()
            thumbnails[oldest] = nil
        }
    }
}

