// MARK: - Continuation helper

/// Guarantees a `CheckedContinuation` resumes at most once, and resumes it
/// immediately with `CancellationError` if cancellation arrives before (or
/// races with) the legacy callback firing.
private final class OneShotContinuation<T> {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<T, Error>?
    private var isCancelled = false
    private var isFinished = false

    func activate(_ continuation: CheckedContinuation<T, Error>) {
        lock.lock()
        if isCancelled {
            lock.unlock()
            continuation.resume(throwing: CancellationError())
            return
        }
        self.continuation = continuation
        lock.unlock()
    }

    func cancel() {
        lock.lock()
        guard !isFinished, !isCancelled else { lock.unlock(); return }
        isCancelled = true
        let pending = continuation
        continuation = nil
        lock.unlock()
        pending?.resume(throwing: CancellationError())
    }

    func finish(with result: Result<T, Error>) {
        lock.lock()
        guard !isFinished, !isCancelled else { lock.unlock(); return }
        isFinished = true
        let pending = continuation
        continuation = nil
        lock.unlock()
        pending?.resume(with: result)
    }
}

// MARK: - Modern async/await wrappers

func geocode(_ address: String) async throws -> (Double, Double) {
    let geocoder = LegacyGeocoder()
    let box = OneShotContinuation<(Double, Double)>()
    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
            box.activate(continuation)
            geocoder.geocode(address) { result in
                box.finish(with: result)
            }
        }
    } onCancel: {
        geocoder.cancel()
        box.cancel()
    }
}

final class UploadBridge {
    let progressUpdates: AsyncStream<Double>
    private let progressContinuation: AsyncStream<Double>.Continuation

    init() {
        var continuation: AsyncStream<Double>.Continuation!
        progressUpdates = AsyncStream { continuation = $0 }
        progressContinuation = continuation
    }

    deinit {
        progressContinuation.finish()
    }

    func upload(file: URL) async throws {
        let uploader = LegacyUploader()
        let progressContinuation = self.progressContinuation
        let box = OneShotContinuation<Void>()

        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                box.activate(continuation)
                uploader.onProgress = { value in
                    progressContinuation.yield(value)
                }
                uploader.onFinish = { error in
                    if let error {
                        box.finish(with: .failure(error))
                    } else {
                        box.finish(with: .success(()))
                    }
                }
                uploader.start(file: file)
            }
        } onCancel: {
            uploader.cancel()
            box.cancel()
        }
    }
}

