import UIKit
typealias PlatformImage = UIImage
#elseif canImport(AppKit)
import AppKit
typealias PlatformImage = NSImage
#endif

/// A downloaded thumbnail together with the moment it finished downloading.
///
/// `PlatformImage` isn't guaranteed `Sendable` on every supported platform/SDK, but instances
/// here are never mutated after creation, so crossing the `ThumbnailCache` actor boundary is safe.
struct CachedThumbnail: @unchecked Sendable {
    let image: PlatformImage
    let downloadDate: Date
}

/// Boxes a `CachedThumbnail` so it can be stored in `NSCache`, which requires class values.
private final class CachedThumbnailBox {
    let value: CachedThumbnail
    init(_ value: CachedThumbnail) { self.value = value }
}

/// Shared in-memory cache so scrolling back through the grid doesn't re-download thumbnails.
///
/// Uses `NSCache` (rather than a plain dictionary) so the system can evict entries under
/// memory pressure instead of retaining every downloaded image indefinitely.
actor ThumbnailCache {
    static let shared = ThumbnailCache()

    private let storage = NSCache<NSURL, CachedThumbnailBox>()
    private var inFlightDownloads: [URL: Task<CachedThumbnail, Error>] = [:]

    func thumbnail(for url: URL) -> CachedThumbnail? {
        storage.object(forKey: url as NSURL)?.value
    }

    func insert(_ thumbnail: CachedThumbnail, for url: URL) {
        storage.setObject(CachedThumbnailBox(thumbnail), forKey: url as NSURL)
    }

    /// Returns the cached thumbnail for `url`, downloading it via `download` if needed.
    /// Concurrent callers for the same uncached URL share a single in-flight download.
    func loadedThumbnail(
        for url: URL,
        download: @escaping @Sendable () async throws -> CachedThumbnail
    ) async throws -> CachedThumbnail {
        if let cached = thumbnail(for: url) {
            return cached
        }
        if let existing = inFlightDownloads[url] {
            return try await existing.value
        }

        let task = Task { try await download() }
        inFlightDownloads[url] = task
        do {
            let result = try await task.value
            inFlightDownloads[url] = nil
            insert(result, for: url)
            return result
        } catch {
            inFlightDownloads[url] = nil
            throw error
        }
    }
}

