    let url: URL

    @State private var thumbnail: CachedThumbnail?
    @State private var failed = false

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(Color.secondary.opacity(0.15))

                if let thumbnail {
                    thumbnailImage(thumbnail.image)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                        .clipShape(RoundedRectangle(cornerRadius: 8))
                } else if failed {
                    Image(systemName: "photo")
                        .foregroundStyle(.secondary)
                } else {
                    ProgressView()
                }
            }
            .aspectRatio(1, contentMode: .fit)

            if let downloadDate = thumbnail?.downloadDate {
                Text(downloadDate, format: .relative(presentation: .named))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }
        }
        .task(id: url) {
            await load()
        }
