    private func thumbnailImage(_ image: PlatformImage) -> Image {
        #if canImport(UIKit)
        return Image(uiImage: image)
        #elseif canImport(AppKit)
        return Image(nsImage: image)
        #endif
    }

    private func load() async {
        // Reset so a stale result/failure from a previous URL isn't shown while this one loads.
        thumbnail = nil
        failed = false

        do {
            let result = try await ThumbnailCache.shared.loadedThumbnail(for: url) {
                let (data, response) = try await URLSession.shared.data(from: url)
                guard let httpResponse = response as? HTTPURLResponse,
                      (200..<300).contains(httpResponse.statusCode) else {
                    throw URLError(.badServerResponse)
                }
                guard let image = PlatformImage(data: data) else {
                    throw URLError(.cannotDecodeContentData)
                }
                return CachedThumbnail(image: image, downloadDate: Date())
            }
            guard !Task.isCancelled else { return }
            thumbnail = result
        } catch {
            guard !Task.isCancelled else { return }
            failed = true
        }
    }
}

