final class ModernUploader {
    /// Emits progress values (0.0...1.0) for the upload, then finishes normally on success
    /// or throws on failure. Each call creates its own stream, so concurrent uploads never
    /// share or prematurely close one another's progress.
    ///
    /// Cancelling the consuming task ends iteration (Swift's `AsyncThrowingStream` tears
    /// down on task cancellation), which unblocks the caller immediately. `LegacyUploader`
    /// has no cancellation hook of its own, so the in-flight legacy upload keeps running in
    /// the background even after the stream stops delivering values.
    func upload(file: URL) -> AsyncThrowingStream<Double, Error> {
        let legacy = LegacyUploader()
        return AsyncThrowingStream { continuation in
            legacy.onProgress = { value in
                continuation.yield(value)
            }
            legacy.onFinish = { error in
                if let error {
                    continuation.finish(throwing: error)
                } else {
                    continuation.finish()
                }
            }
            legacy.start(file: file)
        }
    }
}

import Foundation
import SwiftUI

struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []

    private let url = URL(string: "wss://chat.example.com/room")!
    private let session = URLSession(configuration: .default)
    private var task: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private var reconnectWorkItem: DispatchWorkItem?
    private var pendingMessages: [ChatMessage] = []
    private var isCancelled = false

    func connect() {
        isCancelled = false
        reconnectDelay = 1
        openSocket()
    }

    func disconnect() {
        isCancelled = true
        reconnectWorkItem?.cancel()
        reconnectWorkItem = nil
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }

    func send(text: String) {
        let message = ChatMessage(id: UUID().uuidString, author: "me", text: text)
        sendOrQueue(message)
    }

    private func sendOrQueue(_ message: ChatMessage) {
        guard let data = try? JSONEncoder().encode(message),
              let json = String(data: data, encoding: .utf8) else { return }
        guard let task else {
            pendingMessages.append(message)
            return
        }
        task.send(.string(json)) { [weak self] error in
            guard let self, error != nil else { return }
            Task { @MainActor in
                self.pendingMessages.append(message)
                self.scheduleReconnect()
            }
        }
    }

    private func flushPending() {
        guard task != nil, !pendingMessages.isEmpty else { return }
        let toSend = pendingMessages
        pendingMessages.removeAll()
        for message in toSend {
            sendOrQueue(message)
        }
    }

    private func openSocket() {
        reconnectWorkItem?.cancel()
        reconnectWorkItem = nil
        let newTask = session.webSocketTask(with: url)
        task = newTask
        newTask.resume()
        flushPending()
        receiveNext()
    }

    private func receiveNext() {
        task?.receive { [weak self] result in
            guard let self else { return }
            Task { @MainActor in
                switch result {
                case .failure:
                    self.scheduleReconnect()
                case .success(let message):
                    self.handle(message)
                    self.receiveNext()
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data?
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = text.data(using: .utf8)
        @unknown default:
            data = nil
        }
        guard let data, let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else {
            return
        }
        messages.append(chatMessage)
    }

    private func scheduleReconnect() {
        guard !isCancelled else { return }
        guard reconnectWorkItem == nil else { return }
        task = nil
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, 30)
        let workItem = DispatchWorkItem { [weak self] in
            guard let self, !self.isCancelled else { return }
            self.reconnectWorkItem = nil
            self.openSocket()
        }
        reconnectWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: workItem)
    }
}

struct ChatScreen: View {
    @StateObject private var connection = ChatConnection()
    @State private var draft: String = ""

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(connection.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .padding(.horizontal)
                        }
                    }
                    .padding(.vertical, 8)
                }
                .onChange(of: connection.messages) { messages in
                    guard let lastId = messages.last?.id else { return }
                    withAnimation {
                        proxy.scrollTo(lastId, anchor: .bottom)
                    }
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit(sendDraft)
                Button("Send", action: sendDraft)
                    .disabled(draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { connection.connect() }
        .onDisappear { connection.disconnect() }
    }

    private func sendDraft() {
        let trimmed = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        connection.send(text: trimmed)
        draft = ""
    }
}

