final class LegacyGeocoder {
    func geocode(_ address: String, completion: @escaping (Result<(Double, Double), Error>) -> Void) {
        DispatchQueue.global().asyncAfter(deadline: .now() + 0.1) {
            completion(.success((37.7749, -122.4194)))
        }
    }
}

final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    func start(file: URL) {
        DispatchQueue.global().async {
            for step in 1...10 {
                Thread.sleep(forTimeInterval: 0.01)
                self.onProgress?(Double(step) / 10.0)
            }
            self.onFinish?(nil)
        }
    }
}

// MARK: - Modern async/await wrappers

/// Delivers exactly one result to a `CheckedContinuation`, whichever of the
/// legacy completion or a task-cancellation request arrives first. This lets
/// `onCancel` (which can fire concurrently with, or even before, the
/// continuation is installed) resume the continuation with a
/// `CancellationError` even though the legacy SDK has no way to abort the
/// underlying work.
private final class CancellableContinuation<T> {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<T, Error>?
    private var pendingResult: Result<T, Error>?

    func setContinuation(_ continuation: CheckedContinuation<T, Error>) {
        lock.lock()
        if let pendingResult {
            lock.unlock()
            continuation.resume(with: pendingResult)
            return
        }
        self.continuation = continuation
        lock.unlock()
    }

    func resume(with result: Result<T, Error>) {
        lock.lock()
        if let continuation {
            self.continuation = nil
            lock.unlock()
            continuation.resume(with: result)
        } else if pendingResult == nil {
            pendingResult = result
            lock.unlock()
        } else {
            lock.unlock()
        }
    }
}

final class ModernGeocoder {
    private let legacy = LegacyGeocoder()

    func geocode(_ address: String) async throws -> (Double, Double) {
        try Task.checkCancellation()
        let box = CancellableContinuation<(Double, Double)>()
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                box.setContinuation(continuation)
                legacy.geocode(address) { result in
                    box.resume(with: result)
                }
            }
        } onCancel: {
            box.resume(with: .failure(CancellationError()))
        }
    }
}

final class ModernUploader {
    struct Upload {
        let progress: AsyncStream<Double>
        let task: Task<Void, Error>
    }

    /// Starts a new upload with its own dedicated progress stream, so
    /// concurrent or sequential uploads never share (or race over) delivery
    /// of progress events.
    func upload(file: URL) -> Upload {
        var progressContinuation: AsyncStream<Double>.Continuation!
        let progressStream = AsyncStream<Double> { progressContinuation = $0 }

        let task = Task {
            defer { progressContinuation.finish() }
            try Task.checkCancellation()
            let legacy = LegacyUploader()
            let box = CancellableContinuation<Void>()
            try await withTaskCancellationHandler {
                try await withCheckedThrowingContinuation { continuation in
                    box.setContinuation(continuation)
                    legacy.onProgress = { progress in
                        progressContinuation.yield(progress)
                    }
                    legacy.onFinish = { error in
                        if let error {
                            box.resume(with: .failure(error))
                        } else {
                            box.resume(with: .success(()))
                        }
                    }
                    legacy.start(file: file)
                }
            } onCancel: {
                box.resume(with: .failure(CancellationError()))
            }
        }

        return Upload(progress: progressStream, task: task)
    }
}

import Foundation
import SwiftUI

struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatViewModel: NSObject, ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published var draft: String = ""

    private let url: URL
    private let currentAuthor: String
    private let session: URLSession
    private var task: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var isStopped = false
    private var isActive = false
    private var generation = 0

    nonisolated static let defaultRoomURL: URL = {
        guard let url = URL(string: "wss://chat.example.com/room") else {
            preconditionFailure("Invalid default chat room URL")
        }
        return url
    }()

    init(url: URL = ChatViewModel.defaultRoomURL, currentAuthor: String = "Me") {
        self.url = url
        self.currentAuthor = currentAuthor
        self.session = URLSession(configuration: .default)
        super.init()
    }

    func start() {
        guard !isActive else { return }
        isActive = true
        isStopped = false
        connect()
    }

    func stop() {
        isStopped = true
        isActive = false
        generation += 1
        reconnectDelay = 1
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }

    func sendDraft() {
        let trimmed = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        let message = ChatMessage(id: UUID().uuidString, author: currentAuthor, text: trimmed)
        if send(message) {
            draft = ""
        }
    }

    private func connect() {
        guard !isStopped else { return }
        generation += 1
        let generation = generation
        let newTask = session.webSocketTask(with: url)
        task = newTask
        newTask.resume()
        receiveNext(generation: generation)
    }

    private func receiveNext(generation: Int) {
        guard let task, generation == self.generation else { return }
        task.receive { [weak self] result in
            guard let self else { return }
            Task { @MainActor in
                guard generation == self.generation else { return }
                switch result {
                case .success(let message):
                    self.reconnectDelay = 1
                    self.handle(message)
                    self.receiveNext(generation: generation)
                case .failure:
                    self.scheduleReconnect(generation: generation)
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = Data(text.utf8)
        @unknown default:
            return
        }
        guard let decoded = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        if let index = messages.firstIndex(where: { $0.id == decoded.id }) {
            messages[index] = decoded
        } else {
            messages.append(decoded)
        }
    }

    @discardableResult
    private func send(_ message: ChatMessage) -> Bool {
        guard let data = try? JSONEncoder().encode(message),
              let text = String(data: data, encoding: .utf8),
              let task else { return false }
        let generation = self.generation
        messages.append(message)
        task.send(.string(text)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                guard let self, generation == self.generation else { return }
                self.scheduleReconnect(generation: generation)
            }
        }
        return true
    }

    private func scheduleReconnect(generation: Int) {
        guard !isStopped, generation == self.generation else { return }
        task?.cancel(with: .abnormalClosure, reason: nil)
        task = nil
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            guard let self, generation == self.generation else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var viewModel: ChatViewModel

    init(url: URL = ChatViewModel.defaultRoomURL) {
        _viewModel = StateObject(wrappedValue: ChatViewModel(url: url))
    }

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(viewModel.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundColor(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .padding()
                }
                .onChange(of: viewModel.messages) { messages in
                    guard let lastID = messages.last?.id else { return }
                    withAnimation {
                        proxy.scrollTo(lastID, anchor: .bottom)
                    }
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $viewModel.draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit { viewModel.sendDraft() }
                Button("Send") { viewModel.sendDraft() }
                    .disabled(viewModel.draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { viewModel.start() }
        .onDisappear { viewModel.stop() }
    }
}

import Foundation
import SwiftUI

struct ChatMessage: Identifiable, Codable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatViewModel: ObservableObject {
    @Published var messages: [ChatMessage] = []
    @Published var draftText: String = ""

    private let url: URL = {
        guard let url = URL(string: "wss://chat.example.com/room") else {
            preconditionFailure("Invalid chat room URL")
        }
        return url
    }()
    private let session = URLSession(configuration: .default)
    private var webSocketTask: URLSessionWebSocketTask?
    private var reconnectTask: Task<Void, Never>?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var isStopped = false
    private var connectionID = 0

    func start() {
        guard isStopped || (webSocketTask == nil && reconnectTask == nil) else { return }
        isStopped = false
        connect()
    }

    func stop() {
        isStopped = true
        connectionID += 1
        reconnectTask?.cancel()
        reconnectTask = nil
        webSocketTask?.cancel(with: .goingAway, reason: nil)
        webSocketTask = nil
    }

    private func connect() {
        reconnectTask = nil
        connectionID += 1
        let generation = connectionID
        let task = session.webSocketTask(with: url)
        webSocketTask = task
        task.resume()
        receiveNext(generation: generation, task: task)
    }

    private func receiveNext(generation: Int, task: URLSessionWebSocketTask) {
        task.receive { [weak self] result in
            Task { @MainActor [weak self] in
                guard let self, generation == self.connectionID, task === self.webSocketTask else { return }
                switch result {
                case .success(let message):
                    self.reconnectDelay = 1
                    self.handle(message)
                    self.receiveNext(generation: generation, task: task)
                case .failure:
                    self.scheduleReconnect(generation: generation)
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data?
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = text.data(using: .utf8)
        @unknown default:
            data = nil
        }
        guard let data, let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
    }

    private func scheduleReconnect(generation: Int) {
        guard !isStopped, generation == connectionID, reconnectTask == nil else { return }
        webSocketTask = nil
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        reconnectTask = Task { [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard let self, !Task.isCancelled else { return }
            if !self.isStopped {
                self.connect()
            }
        }
    }

    func sendDraft() {
        let trimmed = draftText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task = webSocketTask else { return }
        let generation = connectionID
        let outgoing = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(outgoing) else { return }
        task.send(.data(data)) { [weak self] error in
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard error == nil else {
                    if generation == self.connectionID, task === self.webSocketTask {
                        self.scheduleReconnect(generation: generation)
                    }
                    return
                }
                self.messages.append(outgoing)
                if self.draftText == trimmed {
                    self.draftText = ""
                }
            }
        }
    }
}

struct ChatScreen: View {
    @StateObject private var viewModel = ChatViewModel()

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(viewModel.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .padding()
                }
                .onChange(of: viewModel.messages) { _ in
                    scrollToBottom(proxy: proxy)
                }
                .onAppear {
                    scrollToBottom(proxy: proxy)
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $viewModel.draftText)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit { viewModel.sendDraft() }
                Button("Send") { viewModel.sendDraft() }
                    .disabled(viewModel.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { viewModel.start() }
        .onDisappear { viewModel.stop() }
    }

    private func scrollToBottom(proxy: ScrollViewProxy) {
        guard let lastId = viewModel.messages.last?.id else { return }
        withAnimation {
            proxy.scrollTo(lastId, anchor: .bottom)
        }
    }
}
